# -----------------------------------------------------------------------------
# V12 · Persistent Daily Memory + Retroactive Logging
# -----------------------------------------------------------------------------
# PostgreSQL is used automatically when DATABASE_URL is configured and
# psycopg2 is installed. Until then THE LAB falls back to SQLite so this single
# app.py still starts normally. The fallback is useful for local/testing use but
# is NOT durable across Render instance replacement/redeploys.
DATABASE_URL = (os.environ.get("DATABASE_URL") or "").strip()
# Render Free PostgreSQL currently provides a 1 GB storage allowance for this
# instance. Keep the limit configurable so the UI stays correct if the plan
# changes later without requiring a code rewrite.
try:
    DATABASE_STORAGE_LIMIT_BYTES = int(os.environ.get("THE_LAB_DB_LIMIT_BYTES", "1000000000"))
except (TypeError, ValueError):
    DATABASE_STORAGE_LIMIT_BYTES = 1_000_000_000
SQLITE_PATH = os.environ.get(
    "THE_LAB_SQLITE_PATH",
    os.path.join(os.path.dirname(os.path.abspath(__file__)), "the_lab_memory.sqlite3"),
)
_DB_READY = False


def storage_status():
    if DATABASE_URL and psycopg2 is not None:
        return {"persistent": True, "label": "PERSISTENT", "detail": "PostgreSQL"}
    if DATABASE_URL and psycopg2 is None:
        return {"persistent": False, "label": "LOCAL FALLBACK", "detail": "Install psycopg2-binary to use DATABASE_URL"}
    return {"persistent": False, "label": "LOCAL FALLBACK", "detail": "SQLite · configure Render PostgreSQL for durable memory"}


def _human_bytes(value):
    try:
        value = max(0, int(value or 0))
    except (TypeError, ValueError):
        value = 0
    units = ("B", "KB", "MB", "GB", "TB")
    size = float(value)
    for unit in units:
        if size < 1000 or unit == units[-1]:
            if unit == "B":
                return f"{int(size)} {unit}"
            return f"{size:.1f} {unit}"
        size /= 1000.0
    return f"{value} B"


def _count_rows(table, where="", params=()):
    row = _db_execute(f"SELECT COUNT(*) AS n FROM {table} {where}", params, fetch=True)
    return int(row[0].get("n") or 0) if row else 0


def get_storage_metrics():
    """Return real database size plus record counts. Never calls Claude or Intervals."""
    init_memory_db()
    if _db_is_postgres():
        rows = _db_execute("SELECT pg_database_size(current_database()) AS bytes", fetch=True)
        used = int(rows[0].get("bytes") or 0) if rows else 0
        limit_bytes = DATABASE_STORAGE_LIMIT_BYTES
        backend = "PostgreSQL"
    else:
        try:
            used = os.path.getsize(SQLITE_PATH) if os.path.exists(SQLITE_PATH) else 0
        except OSError:
            used = 0
        limit_bytes = DATABASE_STORAGE_LIMIT_BYTES
        backend = "SQLite fallback"

    pct = round((used / limit_bytes) * 100, 2) if limit_bytes else 0.0
    if pct >= 95:
        zone = "red"
        message = "CRITICAL · export and clean up now"
    elif pct >= 85:
        zone = "orange"
        message = "HIGH · review archived and old records"
    elif pct >= 70:
        zone = "yellow"
        message = "WATCH · storage is filling up"
    else:
        zone = "green"
        message = "HEALTHY · no cleanup needed"

    counts = {
        "daily_logs": _count_rows("daily_logs"),
        "memory_active": _count_rows("memory_items", "WHERE active=1"),
        "memory_archived": _count_rows("memory_items", "WHERE active=0"),
        "planning_active": _count_rows("planning_items", "WHERE active=1"),
        "planning_archived": _count_rows("planning_items", "WHERE active=0"),
    }
    counts["archived_total"] = counts["memory_archived"] + counts["planning_archived"]
    counts["total_records"] = counts["daily_logs"] + counts["memory_active"] + counts["memory_archived"] + counts["planning_active"] + counts["planning_archived"]

    return {
        "backend": backend,
        "used_bytes": used,
        "limit_bytes": limit_bytes,
        "used_human": _human_bytes(used),
        "limit_human": _human_bytes(limit_bytes),
        "pct": pct,
        "bar_pct": min(100, max(0, pct)),
        "zone": zone,
        "message": message,
        "counts": counts,
    }


def _db_is_postgres():
    return bool(DATABASE_URL and psycopg2 is not None)


def _db_connect():
    if _db_is_postgres():
        return psycopg2.connect(DATABASE_URL)
    conn = sqlite3.connect(SQLITE_PATH, timeout=15)
    conn.row_factory = sqlite3.Row
    return conn


def _db_sql(sql):
    return sql.replace("?", "%s") if _db_is_postgres() else sql


def init_memory_db():
    global _DB_READY
    if _DB_READY:
        return
    conn = _db_connect()
    try:
        cur = conn.cursor()
        statements = [
            """CREATE TABLE IF NOT EXISTS daily_logs (
                id TEXT PRIMARY KEY,
                logged_at_utc TEXT NOT NULL,
                local_date TEXT NOT NULL,
                local_time TEXT NOT NULL,
                feeling INTEGER NOT NULL,
                note TEXT,
                status TEXT NOT NULL,
                status_until TEXT,
                restriction_type TEXT,
                restriction_until TEXT,
                phase TEXT,
                session_count INTEGER,
                today_load REAL,
                am_done INTEGER,
                pm_done INTEGER,
                context_source TEXT
            )""",
            """CREATE TABLE IF NOT EXISTS memory_items (
                id TEXT PRIMARY KEY,
                created_at_utc TEXT NOT NULL,
                updated_at_utc TEXT NOT NULL,
                category TEXT NOT NULL,
                text TEXT NOT NULL,
                active INTEGER NOT NULL DEFAULT 1
            )""",
            """CREATE TABLE IF NOT EXISTS planning_items (
                id TEXT PRIMARY KEY,
                created_at_utc TEXT NOT NULL,
                kind TEXT NOT NULL,
                title TEXT NOT NULL,
                note TEXT,
                start_date TEXT NOT NULL,
                end_date TEXT NOT NULL,
                restriction_type TEXT NOT NULL DEFAULT 'NONE',
                active INTEGER NOT NULL DEFAULT 1
            )""",
        ]
        for statement in statements:
            cur.execute(statement)
        conn.commit()
        _DB_READY = True
    finally:
        conn.close()


def _db_execute(sql, params=(), fetch=False):
    init_memory_db()
    conn = _db_connect()
    try:
        cur = conn.cursor()
        cur.execute(_db_sql(sql), params)
        rows = []
        if fetch:
            raw = cur.fetchall()
            if _db_is_postgres():
                cols = [d[0] for d in cur.description]
                rows = [dict(zip(cols, row)) for row in raw]
            else:
                rows = [dict(row) for row in raw]
        conn.commit()
        return rows
    finally:
        conn.close()


def _now_utc_text():
    return datetime.utcnow().replace(microsecond=0).isoformat() + "Z"


def _safe_iso_date(value, fallback=None):
    value = (value or "").strip()
    try:
        return date.fromisoformat(value).isoformat()
    except (ValueError, TypeError):
        return fallback


def format_ui_date(value):
    """Render stored ISO dates as DD/MM/YYYY without changing database storage."""
    if value in (None, ""):
        return "—"
    try:
        return date.fromisoformat(str(value)[:10]).strftime("%d/%m/%Y")
    except (ValueError, TypeError):
        return str(value)


def format_ui_time(value):
    """Render HH:MM values using a 12-hour clock with AM/PM."""
    if value in (None, ""):
        return "—"
    raw = str(value).strip()
    for fmt in ("%H:%M", "%H:%M:%S"):
        try:
            return datetime.strptime(raw, fmt).strftime("%I:%M %p")
        except ValueError:
            pass
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00")).strftime("%I:%M %p")
    except (ValueError, TypeError):
        return raw


app.add_template_filter(format_ui_date, "ui_date")
app.add_template_filter(format_ui_time, "ui_time")


def add_memory_item(text, category="GENERAL"):
    text = (text or "").strip()
    if not text:
        return None
    now = _now_utc_text()
    item_id = uuid.uuid4().hex
    _db_execute(
        "INSERT INTO memory_items (id, created_at_utc, updated_at_utc, category, text, active) VALUES (?, ?, ?, ?, ?, 1)",
        (item_id, now, now, (category or "GENERAL").strip().upper(), text),
    )
    return item_id


def archive_memory_item(item_id):
    _db_execute("UPDATE memory_items SET active=0, updated_at_utc=? WHERE id=?", (_now_utc_text(), item_id))


def restore_memory_item(item_id):
    _db_execute("UPDATE memory_items SET active=1, updated_at_utc=? WHERE id=?", (_now_utc_text(), item_id))


def update_memory_item(item_id, text, category="GENERAL"):
    text = (text or "").strip()
    if not text:
        raise ValueError("Memory text cannot be empty")
    _db_execute(
        "UPDATE memory_items SET text=?, category=?, updated_at_utc=? WHERE id=?",
        (text, (category or "GENERAL").strip().upper(), _now_utc_text(), item_id),
    )


def delete_archived_memory_item(item_id):
    _db_execute("DELETE FROM memory_items WHERE id=? AND active=0", (item_id,))


