def get_intervals_headers():
    credentials = f"API_KEY:{ICU_API_KEY}"
    encoded = base64.b64encode(credentials.encode("utf-8")).decode("utf-8")
    return {"Authorization": f"Basic {encoded}"}


def fetch_power_curve_payload(newest=None):
    """Fetch the athlete 42-day cycling power curve.

    Intervals.icu exposes a ``newest`` parameter on this endpoint. Keeping it
    optional preserves the existing Best Wattage Output behaviour while also
    letting THE LAB inspect the same 42-day curve at historical checkpoints
    for the performance-derived VO2max trend.
    """
    headers = get_intervals_headers()
    url = (
        f"https://intervals.icu/api/v1/athlete/{ICU_ATHLETE_ID}/power-curves.json"
        f"?type=Ride&curves=42d"
    )
    if newest:
        url += f"&newest={newest}"
    resp = requests.get(url, headers=headers, timeout=30)
    resp.raise_for_status()
    return resp.json()


def extract_power_curve_points(payload):
    """The exact shape of this endpoint's response isn't officially documented.
    The real shape turned out to be a curve object with PARALLEL ARRAYS -
    e.g. {"secs": [5, 10, 15, ...], "watts": [900, 850, ...]} - rather than a
    list of {secs, watts} point dicts. Handle that first, and keep the
    point-list shape as a fallback in case a different curve type (e.g. "all")
    is structured differently."""
    array_results = []
    point_list_results = []

    def walk(node):
        if isinstance(node, dict):
            secs = node.get("secs")
            watts = node.get("watts")
            if watts is None:
                watts = node.get("power")
            if (
                isinstance(secs, list) and isinstance(watts, list)
                and len(secs) == len(watts) and len(secs) > 0
                and isinstance(secs[0], (int, float))
            ):
                array_results.append(
                    [{"secs": s, "watts": w} for s, w in zip(secs, watts) if w]
                )
            for v in node.values():
                walk(v)
        elif isinstance(node, list):
            if node and all(isinstance(i, dict) for i in node):
                keys0 = set(node[0].keys())
                if "secs" in keys0 and ("watts" in keys0 or "power" in keys0):
                    if isinstance(node[0].get("secs"), (int, float)):
                        point_list_results.append(node)
            for item in node:
                walk(item)

    walk(payload)
    if array_results:
        return max(array_results, key=len)
    return point_list_results[0] if point_list_results else None


def format_duration_label(secs):
    if secs < 60:
        return f"{secs}s"
    if secs < 3600:
        return f"{secs // 60}min"
    return f"{secs // 3600}h"


def best_watts_for_durations(points, target_secs_list):
    if not points:
        return []
    sorted_points = sorted(points, key=lambda p: p.get("secs", 0))
    results = []
    for target in target_secs_list:
        best = None
        for p in sorted_points:
            if p.get("secs", 0) <= target:
                best = p
            else:
                break
        if best is None:
            best = sorted_points[0]
        watts = best.get("watts") or best.get("power")
        if watts:
            results.append({"label": format_duration_label(target), "watts": round(watts)})

    if results:
        max_watts = max(r["watts"] for r in results)
        for r in results:
            r["pct"] = round(100 * r["watts"] / max_watts) if max_watts else 0
    return results


def get_best_watts():
    try:
        payload = fetch_power_curve_payload()
        points = extract_power_curve_points(payload)
        result = best_watts_for_durations(points, [5, 15, 60, 300, 1200, 3600])
        debug = None
        if not result:
            preview = json.dumps(payload)[:500]
            debug = "Power curve payload preview: {}".format(preview)
        return result, debug
    except requests.HTTPError as e:
        return [], "Power curve request failed: {}".format(e)
    except Exception as e:
        return [], "Power curve error: {}".format(e)


def fetch_intervals_data():
    """Fetch SEASON_DAYS_BACK days of activities (with zone times) AND
    wellness. Wellness needs the longer window too now, so we can learn the
    athlete's own normal range for Form/Fatigue instead of judging them
    against generic fixed thresholds. The recent-window subsets are simply
    the tail end of these season-length lists."""
    season_oldest = (date.today() - timedelta(days=SEASON_DAYS_BACK)).isoformat()
    recent_oldest = (date.today() - timedelta(days=DAYS_BACK)).isoformat()
    newest = date.today().isoformat()
    headers = get_intervals_headers()

    activities_fields = (
        "id,name,type,start_date_local,moving_time,elapsed_time,distance,"
        "icu_training_load,icu_weighted_avg_watts,average_watts,average_heartrate,"
        "icu_zone_times,calories,carbs_used,carbs_ingested,trainer,icu_intensity,"
        "icu_variability_index,joules,sub_type"
    )
    activities_url = (
        f"https://intervals.icu/api/v1/athlete/{ICU_ATHLETE_ID}/activities"
        f"?oldest={season_oldest}&newest={newest}&fields={activities_fields}"
    )

    wellness_fields = "id,restingHR,hrv,sleepSecs,sleepScore,sleepQuality,avgSleepingHR,weight,ctl,atl,rampRate,comments,readiness,spO2,vo2max"
    wellness_url = (
        f"https://intervals.icu/api/v1/athlete/{ICU_ATHLETE_ID}/wellness"
        f"?oldest={season_oldest}&newest={newest}&fields={wellness_fields}"
    )

    act_resp = requests.get(activities_url, headers=headers, timeout=30)
    act_resp.raise_for_status()
    wel_resp = requests.get(wellness_url, headers=headers, timeout=30)
    wel_resp.raise_for_status()

    season_activities = act_resp.json()
    season_activities = [
        a for a in season_activities if a.get("start_date_local", "")[:10] >= season_oldest
    ]
    recent_activities = [
        a for a in season_activities if a.get("start_date_local", "")[:10] >= recent_oldest
    ]

    season_wellness = wel_resp.json()
    season_wellness = [
        w for w in season_wellness if w.get("id", "") >= season_oldest
    ]
    recent_wellness = [w for w in season_wellness if w.get("id", "") >= recent_oldest]

    return recent_activities, season_activities, recent_wellness, season_wellness


def _vo2_number(value):
    try:
        value = float(value)
    except (TypeError, ValueError):
        return None
    # Sanity filter only; this is not a physiological classification.
    return value if 15.0 <= value <= 100.0 else None


def extract_vo2max_5m(payload):
    """Return Intervals.icu's performance VO2max estimate from a power curve.

    The Intervals.icu server-side power-curve model exposes ``vo2max_5m``.
    The public endpoint payload can contain nested curve objects, so search
    recursively and keep a plausible numeric value. The URL asks only for the
    42-day Ride curve; if several nested representations are present we retain
    the highest identical/near-identical estimate rather than inventing a
    value from average power.
    """
    values = []

    def walk(node):
        if isinstance(node, dict):
            if "vo2max_5m" in node:
                v = _vo2_number(node.get("vo2max_5m"))
                if v is not None:
                    values.append(v)
            for value in node.values():
                walk(value)
        elif isinstance(node, list):
            for item in node:
                walk(item)

    walk(payload)
    return round(max(values), 1) if values else None


def _sample_vo2_points(points, max_points=10):
    if len(points) <= max_points:
        return points
    if max_points <= 1:
        return [points[-1]]
    # Evenly retain the full time span, always keeping first and latest.
    idxs = []
    for i in range(max_points):
        idx = round(i * (len(points) - 1) / (max_points - 1))
        if idx not in idxs:
            idxs.append(idx)
    return [points[i] for i in idxs]


def build_wearable_vo2_series(wellness, max_points=10):
    """VO2max imported through Intervals wellness (typically wearable data).

    Consecutive identical values are collapsed to the *latest* date carrying
    that value. This keeps the chart readable instead of printing the same
    wearable estimate on dozens of consecutive days.
    """
    raw = []
    for w in sorted(wellness or [], key=lambda x: x.get("id", "")):
        v = _vo2_number(w.get("vo2max"))
        day = str(w.get("id") or "")[:10]
        if v is None or len(day) != 10:
            continue
        item = {"date": day, "value": round(v, 1)}
        if raw and abs(raw[-1]["value"] - item["value"]) < 0.05:
            raw[-1] = item
        else:
            raw.append(item)
    return _sample_vo2_points(raw, max_points=max_points)


def _performance_vo2_checkpoint(day):
    payload = fetch_power_curve_payload(newest=day.isoformat())
    value = extract_vo2max_5m(payload)
    return {"date": day.isoformat(), "value": value} if value is not None else None


def build_performance_vo2_series(points=8, step_days=7):
    """Historical Intervals 5-minute-power VO2max trend.

    Intervals' athlete power-curve endpoint accepts ``newest`` and the 42-day
    curve carries ``vo2max_5m``. Query a small number of weekly checkpoints in
    parallel. This is intentionally low-resolution: it is a longitudinal
    context signal, not a readiness metric and not a laboratory measurement.
    """
    today = date.today()
    checkpoints = [today - timedelta(days=step_days * i) for i in reversed(range(points))]
    results = []
    try:
        with ThreadPoolExecutor(max_workers=4) as pool:
            futures = {pool.submit(_performance_vo2_checkpoint, d): d for d in checkpoints}
            for future in as_completed(futures):
                try:
                    item = future.result()
                    if item:
                        results.append(item)
                except Exception:
                    # One failed historical checkpoint must never break a snapshot.
                    pass
    except Exception:
        return []
    results.sort(key=lambda x: x["date"])
    # Rolling 42-day values often remain unchanged for several checkpoints.
    # Keep all weekly checkpoints because the flat portions are meaningful.
    return results


def _vo2_delta_28(series):
    if len(series) < 2:
        return None
    latest = series[-1]
    try:
        latest_day = date.fromisoformat(latest["date"])
    except Exception:
        return None
    target = latest_day - timedelta(days=28)
    candidates = []
    for p in series[:-1]:
        try:
            d = date.fromisoformat(p["date"])
        except Exception:
            continue
        candidates.append((abs((d - target).days), d, p))
    if not candidates:
        return None
    _, _, base = min(candidates, key=lambda x: x[0])
    return round(latest["value"] - base["value"], 1)


def _vo2_direction(delta):
    if delta is None:
        return None
    if delta >= 0.5:
        return "RISING"
    if delta <= -0.5:
        return "FALLING"
    return "STABLE"


def _vo2_path(points):
    return " ".join(("M" if i == 0 else "L") + f" {p['x']:.1f} {p['y']:.1f}" for i, p in enumerate(points))


def build_vo2max_trend(season_wellness):
    wearable = build_wearable_vo2_series(season_wellness, max_points=10)
    performance = build_performance_vo2_series(points=8, step_days=7)

    all_points = wearable + performance
    if not all_points:
        return {
            "available": False, "wearable": [], "performance": [],
            "wearable_current": None, "performance_current": None,
            "wearable_delta28": None, "performance_delta28": None,
            "agreement": "INSUFFICIENT DATA", "agreement_class": "grey",
        }

    dated = []
    for p in all_points:
        try:
            dated.append((date.fromisoformat(p["date"]), float(p["value"])))
        except Exception:
            pass
    if not dated:
        return {"available": False, "wearable": [], "performance": [], "agreement": "INSUFFICIENT DATA", "agreement_class": "grey"}

    min_day = min(d for d, _ in dated)
    max_day = max(d for d, _ in dated)
    day_span = max(1, (max_day - min_day).days)
    values = [v for _, v in dated]
    vmin, vmax = min(values), max(values)
    pad = max(1.0, (vmax - vmin) * 0.18)
    ymin = math.floor((vmin - pad) * 2) / 2
    ymax = math.ceil((vmax + pad) * 2) / 2
    if ymax - ymin < 4:
        mid = (ymax + ymin) / 2
        ymin, ymax = mid - 2, mid + 2

    x0, x1 = 58.0, 942.0
    y0, y1 = 32.0, 188.0

    def map_series(series, label_offset):
        mapped = []
        for p in series:
            d = date.fromisoformat(p["date"])
            x = x0 + ((d - min_day).days / day_span) * (x1 - x0)
            y = y1 - ((p["value"] - ymin) / (ymax - ymin)) * (y1 - y0)
            mapped.append({
                **p,
                "x": round(x, 1), "y": round(y, 1),
                "label_y": round(max(17, min(211, y + label_offset)), 1),
                "date_label": d.strftime("%d %b"),
                "value_label": f"{p['value']:.1f}",
            })
        return mapped

    wearable_m = map_series(wearable, -12)
    performance_m = map_series(performance, 21)
    wd = _vo2_delta_28(wearable)
    pd = _vo2_delta_28(performance)
    wdir, pdir = _vo2_direction(wd), _vo2_direction(pd)
    if wdir is None or pdir is None:
        agreement = "INSUFFICIENT DATA"
        agreement_class = "grey"
    elif wdir == "RISING" and pdir == "RISING":
        agreement, agreement_class = "BOTH RISING", "green"
    elif wdir == "STABLE" and pdir == "STABLE":
        agreement, agreement_class = "BOTH STABLE", "cyan"
    elif {wdir, pdir} == {"RISING", "FALLING"}:
        agreement, agreement_class = "DIVERGING", "orange"
    else:
        agreement, agreement_class = "MIXED", "grey"

    ticks = []
    for frac in (0.0, 0.5, 1.0):
        value = ymax - frac * (ymax - ymin)
        ticks.append({"y": round(y0 + frac * (y1 - y0), 1), "value": round(value, 1)})

    date_ticks = []
    for frac in (0.0, 0.5, 1.0):
        d = min_day + timedelta(days=round(day_span * frac))
        date_ticks.append({"x": round(x0 + frac * (x1 - x0), 1), "label": d.strftime("%d %b")})

    return {
        "available": True,
        "wearable": wearable_m,
        "performance": performance_m,
        "wearable_path": _vo2_path(wearable_m) if wearable_m else "",
        "performance_path": _vo2_path(performance_m) if performance_m else "",
        "wearable_current": wearable[-1]["value"] if wearable else None,
        "performance_current": performance[-1]["value"] if performance else None,
        "wearable_delta28": wd,
        "performance_delta28": pd,
        "wearable_direction": wdir or "INSUFFICIENT",
        "performance_direction": pdir or "INSUFFICIENT",
        "agreement": agreement,
        "agreement_class": agreement_class,
        "ticks": ticks,
        "date_ticks": date_ticks,
        "ymin": ymin, "ymax": ymax,
    }


def percentile(sorted_values, pct):
    """Simple linear-interpolation percentile, no numpy dependency."""
    if not sorted_values:
        return None
    if len(sorted_values) == 1:
        return sorted_values[0]
    k = (len(sorted_values) - 1) * pct
    f, c = int(k), min(int(k) + 1, len(sorted_values) - 1)
    if f == c:
        return sorted_values[f]
    return sorted_values[f] + (sorted_values[c] - sorted_values[f]) * (k - f)


def personal_form_thresholds(season_wellness, min_points=14):
    """The athlete's own p33/p67 TSB range over the season window, so Form is
    judged against their normal baseline instead of a generic cutoff."""
    tsb_values = sorted(
        w["ctl"] - w["atl"] for w in season_wellness
        if w.get("ctl") is not None and w.get("atl") is not None
    )
    if len(tsb_values) < min_points:
        return None
    return percentile(tsb_values, 0.33), percentile(tsb_values, 0.67)


def personal_form_median(season_wellness, min_points=14):
    """The athlete's own typical TSB, so day-to-day form can be shown as a
    small delta from what's normal FOR THEM instead of a scary absolute
    number that's just a side effect of training at chronic high load."""
    tsb_values = sorted(
        w["ctl"] - w["atl"] for w in season_wellness
        if w.get("ctl") is not None and w.get("atl") is not None
    )
    if len(tsb_values) < min_points:
        return None
    return percentile(tsb_values, 0.5)


def personal_fatigue_thresholds(season_wellness, min_points=14):
    """The athlete's own p33/p67 ATL:CTL ratio range over the season window."""
    ratios = sorted(
        w["atl"] / w["ctl"] for w in season_wellness
        if w.get("ctl") not in (None, 0) and w.get("atl") is not None
    )
    if len(ratios) < min_points:
        return None
    return percentile(ratios, 0.33), percentile(ratios, 0.67)


def classify_form(tsb, personal_thresholds=None):
    if tsb is None:
        return "grey"
    if personal_thresholds:
        p33, p67 = personal_thresholds
        if tsb >= p67:
            return "green"
        if tsb <= p33:
            return "red"
        return "grey"
    # Fallback generic thresholds - only used when there isn't enough
    # history yet to learn the athlete's own normal range.
    if tsb >= 5:
        return "green"
    if tsb <= -10:
        return "red"
    return "grey"


def classify_fatigue(atl, ctl, personal_thresholds=None):
    if atl is None or ctl is None or ctl == 0:
        return "grey"
    ratio = atl / ctl
    if personal_thresholds:
        p33, p67 = personal_thresholds
        if ratio <= p33:
            return "green"
        if ratio >= p67:
            return "red"
        return "grey"
    if ratio >= 1.15:
        return "red"
    if ratio <= 0.95:
        return "green"
    return "grey"


def classify_fitness_trend(wellness):
    ctl_values = [(w.get("id"), w.get("ctl")) for w in wellness if w.get("ctl") is not None]
    ctl_values.sort(key=lambda x: x[0])
    if len(ctl_values) < 2:
        return "grey"
    change = ctl_values[-1][1] - ctl_values[0][1]
    if change >= 2:
        return "green"
    if change <= -2:
        return "red"
    return "grey"


def bucket_zone_seconds(zone_seconds):
    """Given an ordered list of seconds-per-zone (easiest to hardest), bucket
    into Low / Moderate / High using common Coggan-style zone groupings."""
    n = len(zone_seconds)
    if n == 0:
        return 0, 0, 0
    if n == 3:
        low, mod, high = zone_seconds[0], zone_seconds[1], zone_seconds[2]
    elif n in (5, 6):
        low = sum(zone_seconds[0:2])
        mod = zone_seconds[2] if n == 5 else sum(zone_seconds[2:4])
        high = sum(zone_seconds[3:]) if n == 5 else sum(zone_seconds[4:])
    elif n == 7:
        low = sum(zone_seconds[0:2])
        mod = sum(zone_seconds[2:4])
        high = sum(zone_seconds[4:])
    else:
        third = max(1, n // 3)
        low = sum(zone_seconds[0:third])
        mod = sum(zone_seconds[third:2 * third])
        high = sum(zone_seconds[2 * third:])
    return low, mod, high


def compute_season_stats(season_activities):
    total_secs = 0
    low_secs = mod_secs = high_secs = 0
    total_load = 0

    for a in season_activities:
        total_secs += a.get("moving_time") or a.get("elapsed_time") or 0
        total_load += a.get("icu_training_load") or 0
        zt = a.get("icu_zone_times")
        if zt:
            secs_list = [z.get("secs", 0) for z in zt]
            low, mod, high = bucket_zone_seconds(secs_list)
            low_secs += low
            mod_secs += mod
            high_secs += high

    zone_total = low_secs + mod_secs + high_secs
    if zone_total > 0:
        low_pct = round(100 * low_secs / zone_total)
        mod_pct = round(100 * mod_secs / zone_total)
        high_pct = round(100 * high_secs / zone_total)
    else:
        low_pct = mod_pct = high_pct = None

    return {
        "season_hours": round(total_secs / 3600, 1),
        "season_total_load": round(total_load),
        "zone_low_pct": low_pct if low_pct is not None else "n/a",
        "zone_mod_pct": mod_pct if mod_pct is not None else "n/a",
        "zone_high_pct": high_pct if high_pct is not None else "n/a",
    }


def last_two_values(wellness, field):
    vals = [
        w[field] for w in sorted(wellness, key=lambda x: x.get("id", ""))
        if w.get(field) is not None
    ]
    if len(vals) < 2:
        return None, None
    return vals[-1], vals[-2]


def trend_arrow(current, previous, higher_is_better):
    """higher_is_better: True/False for a directional judgement, or None for
    a neutral metric where up/down isn't inherently good or bad."""
    if current is None or previous is None or current == previous:
        return None
    up = current > previous
    arrow = "▲" if up else "▼"
    if higher_is_better is None:
        color = "grey"
    else:
        good = up if higher_is_better else not up
        color = "green" if good else "red"
    return {"arrow": arrow, "color": color}


def _recent_numeric(wellness, field, days=RECENT_BASELINE_DAYS, exclude_latest=True, divisor=1.0):
    """Numeric recent values for trend context, independent from Garmin's fixed personal baseline."""
    ordered = sorted(wellness, key=lambda x: x.get("id", ""))
    if exclude_latest and ordered:
        ordered = ordered[:-1]
    vals = []
    for w in ordered:
        value = w.get(field)
        if isinstance(value, (int, float)):
            vals.append(value / divisor)
    return vals[-days:]


def _fmt_hours(hours):
    if not isinstance(hours, (int, float)):
        return "n/a"
    total = max(0, round(hours * 60))
    return f"{total // 60}h {total % 60:02d}m"


def _fmt_number(value, decimals=0, suffix=""):
    if not isinstance(value, (int, float)):
        return "n/a"
    rendered = f"{value:.{decimals}f}" if decimals else str(round(value))
    return f"{rendered}{suffix}"


def _range_signal(value, low, high, kind="neutral"):
    """Status versus a personal Garmin range. The ring expresses closeness to normal, not 'performance'."""
    if not isinstance(value, (int, float)):
        return {"color": "grey", "status": "No current data", "pct": 0}
    width = max(high - low, 1)
    if low <= value <= high:
        return {"color": "green", "status": "Within baseline", "pct": 100}
    if value < low:
        distance = low - value
        pct = max(10, round(100 - (distance / width) * 75))
        if kind == "hrv":
            color = "red" if distance > width * 0.25 else "grey"
            status = "Below baseline"
        elif kind == "heart_rate":
            color = "grey" if distance <= 3 else "red"
            status = "Below baseline"
        else:
            color, status = "grey", "Below baseline"
        return {"color": color, "status": status, "pct": pct}
    distance = value - high
    pct = max(10, round(100 - (distance / width) * 75))
    if kind == "hrv":
        color = "green" if distance <= width * 0.25 else "grey"
        status = "Above baseline"
    elif kind == "heart_rate":
        color = "red" if distance > 2 else "grey"
        status = "Above baseline"
    else:
        color, status = "grey", "Above baseline"
    return {"color": color, "status": status, "pct": pct}


def _target_signal(value, target, metric):
    if not isinstance(value, (int, float)):
        return {"color": "grey", "status": "No current data", "pct": 0}
    if metric == "sleep_minutes":
        diff = value - target
        pct = max(10, min(100, round(value / target * 100))) if target else 0
        if diff >= -30:
            return {"color": "green", "status": "On target", "pct": pct}
        if diff >= -75:
            return {"color": "grey", "status": "Below target", "pct": pct}
        return {"color": "red", "status": "Short sleep", "pct": pct}
    if metric == "sleep_score":
        pct = max(10, min(100, round(value)))
        if value >= target - 3:
            return {"color": "green", "status": "Near baseline", "pct": pct}
        if value >= target - 10:
            return {"color": "grey", "status": "Below baseline", "pct": pct}
        return {"color": "red", "status": "Low vs baseline", "pct": pct}
    if metric == "spo2":
        pct = max(10, min(100, round(value)))
        if value >= target - 1:
            return {"color": "green", "status": "Near baseline", "pct": pct}
        if value >= target - 2:
            return {"color": "grey", "status": "Below baseline", "pct": pct}
        return {"color": "red", "status": "Low vs baseline", "pct": pct}
    return {"color": "grey", "status": "Reference", "pct": 0}


def compute_personal_baselines(wellness):
    """Combine Garmin's personal references with rolling 14-day calculations from Intervals.icu."""
    ordered = sorted(wellness, key=lambda x: x.get("id", ""))
    latest = ordered[-1] if ordered else {}

    hrv_recent = _recent_numeric(wellness, "hrv")
    rhr_recent = _recent_numeric(wellness, "restingHR")
    sleep_recent = _recent_numeric(wellness, "sleepSecs", divisor=3600.0)
    score_recent = _recent_numeric(wellness, "sleepScore")
    spo2_recent = _recent_numeric(wellness, "spO2")
    sleeping_hr_recent = _recent_numeric(wellness, "avgSleepingHR")

    current_sleep_minutes = latest.get("sleepSecs") / 60.0 if isinstance(latest.get("sleepSecs"), (int, float)) else None
    current_rhr = latest.get("restingHR")
    current_hrv = latest.get("hrv")
    current_score = latest.get("sleepScore")
    current_sleeping_hr = latest.get("avgSleepingHR")
    spo2_entries = [w for w in ordered if isinstance(w.get("spO2"), (int, float))]
    current_spo2 = spo2_entries[-1].get("spO2") if spo2_entries else None

    rhr_signal = _range_signal(current_rhr, GARMIN_BASELINES["resting_hr_low"], GARMIN_BASELINES["resting_hr_high"], "heart_rate")
    hrv_signal = _range_signal(current_hrv, GARMIN_BASELINES["hrv_low"], GARMIN_BASELINES["hrv_high"], "hrv")
    sleep_signal = _target_signal(current_sleep_minutes, GARMIN_BASELINES["sleep_minutes"], "sleep_minutes")
    score_signal = _target_signal(current_score, GARMIN_BASELINES["sleep_score"], "sleep_score")
    spo2_signal = _target_signal(current_spo2, GARMIN_BASELINES["spo2"], "spo2")
    sleeping_hr_signal = _range_signal(current_sleeping_hr, GARMIN_BASELINES["resting_hr_low"], GARMIN_BASELINES["resting_hr_high"], "heart_rate")

    return {
        "source": BASELINE_SOURCE,
        "days": RECENT_BASELINE_DAYS,
        "rhr": {**rhr_signal, "garmin": "38–44 bpm", "recent": _fmt_number(statistics.median(rhr_recent), 0, " bpm") if rhr_recent else "n/a"},
        "hrv": {**hrv_signal, "garmin": "89–136 ms", "recent": _fmt_number(statistics.median(hrv_recent), 0, " ms") if hrv_recent else "n/a"},
        "sleep": {**sleep_signal, "garmin": "7h 38m", "recent": _fmt_hours(statistics.mean(sleep_recent)) if sleep_recent else "n/a"},
        "sleep_score": {**score_signal, "garmin": "86", "recent": _fmt_number(statistics.mean(score_recent), 0) if score_recent else "n/a"},
        "spo2": {**spo2_signal, "garmin": "97%", "recent": _fmt_number(statistics.median(spo2_recent), 1, "%") if spo2_recent else "n/a"},
        "sleeping_hr": {**sleeping_hr_signal, "garmin": "38–44 bpm", "recent": _fmt_number(statistics.median(sleeping_hr_recent), 0, " bpm") if sleeping_hr_recent else "n/a"},
        "sleeping_respiration": {"garmin": "11 brpm", "recent": "not synced", "color": "grey", "status": "Garmin reference only", "pct": 0},
        "awake_respiration": {"garmin": "13–14 brpm", "recent": "not synced", "color": "grey", "status": "Garmin reference only", "pct": 0},
    }


def compute_health_rings(metrics):
    """Small rings now show closeness to the athlete's Garmin baseline, while arrows still show day-to-day direction."""
    pb = metrics.get("personal_baselines") or {}
    rings = {}
    for key in ("rhr", "hrv", "sleep"):
        item = pb.get(key)
        if item:
            rings[key] = {"pct": item.get("pct", 0), "color": item.get("color", "grey"), "status": item.get("status", "Reference")}
    return rings

def compute_trend_arrows(wellness):
    rhr_latest, rhr_prev = last_two_values(wellness, "restingHR")
    hrv_latest, hrv_prev = last_two_values(wellness, "hrv")
    sleep_latest, sleep_prev = last_two_values(wellness, "sleepSecs")
    weight_latest, weight_prev = last_two_values(wellness, "weight")
    return {
        "rhr": trend_arrow(rhr_latest, rhr_prev, higher_is_better=False),
        "hrv": trend_arrow(hrv_latest, hrv_prev, higher_is_better=True),
        "sleep": trend_arrow(sleep_latest, sleep_prev, higher_is_better=True),
        "weight": trend_arrow(weight_latest, weight_prev, higher_is_better=None),
    }


def compute_recent_trend(wellness, n=5, form_thresholds=None, form_median=None):
    """Daily Form (TSB) for the last n days that have both CTL and ATL, for a
    quick at-a-glance trend next to the Energy Bank. Shown primarily as a
    delta from the athlete's own typical TSB, not the raw absolute number -
    for someone who trains at chronic high load, the raw number is nearly
    always a scary-looking double-digit negative even on a completely
    ordinary day."""
    daily = []
    for w in sorted(wellness, key=lambda x: x.get("id", "")):
        ctl, atl = w.get("ctl"), w.get("atl")
        if ctl is None or atl is None:
            continue
        tsb = round(ctl - atl, 1)
        try:
            weekday = date.fromisoformat(w["id"]).strftime("%a")
        except (ValueError, KeyError):
            weekday = w.get("id", "")[-2:]
        delta = round(tsb - form_median, 1) if form_median is not None else None
        daily.append({
            "date": w.get("id", ""), "weekday": weekday, "tsb": tsb, "delta": delta,
            "zone": classify_form(tsb, form_thresholds),
        })
    return daily[-n:]


def compute_energy_bank(form_zone, fatigue_zone, avg_sleep_hours, recent_activities=None, personal_baselines=None, now=None, sleep_quality=None):
    """Intraday 0-100 energy estimate.

    Morning recovery establishes the potential available for the day. Completed
    activities then spend that potential using Intervals.icu training load,
    duration and session type. Sleep quality is intentionally weighted strongly:
    a good-quality night can partially offset a modest duration deficit, while a
    poor-quality night remains a meaningful recovery penalty.
    """
    now = now or get_rome_now()
    recent_activities = recent_activities or []
    pb = personal_baselines or {}

    # Morning potential. Duration matters, but quality is a first-class signal.
    morning = 62
    morning += {"green": 12, "grey": 0, "red": -14}.get(form_zone, 0)
    morning += {"green": 9, "grey": 0, "red": -11}.get(fatigue_zone, 0)

    if isinstance(avg_sleep_hours, (int, float)):
        if avg_sleep_hours >= 7.5:
            morning += 4
        elif avg_sleep_hours < 6.5:
            morning -= 6
        elif avg_sleep_hours < 7.0:
            morning -= 2

    # Q1/Q2 are intentionally meaningful because weekday sleep duration is often
    # constrained by the athlete's routine. Good quality should prevent a modest
    # short night from being treated as automatically poor recovery.
    if sleep_quality == 1:
        morning += 10
    elif sleep_quality == 2:
        morning += 7
    elif sleep_quality == 3:
        morning -= 3
    elif sleep_quality == 4:
        morning -= 10

    # Recovery signals affect the starting reserve, not the training cost.
    hrv = pb.get("hrv", {})
    rhr = pb.get("rhr", {})
    sleep = pb.get("sleep", {})
    if hrv.get("color") == "red": morning -= 10
    elif hrv.get("color") == "grey": morning -= 4
    if rhr.get("color") == "red": morning -= 7
    elif rhr.get("color") == "grey" and rhr.get("status") == "Above baseline": morning -= 3

    if sleep.get("color") == "red":
        morning -= 2 if sleep_quality in (1, 2) else 7
    elif sleep.get("color") == "grey":
        morning -= 0 if sleep_quality in (1, 2) else 3

    morning = max(25, min(96, round(morning)))

    today = now.date().isoformat()
    today_activities = [a for a in recent_activities if str(a.get("start_date_local", ""))[:10] == today]
    today_load = 0.0
    today_minutes = 0.0
    hard_sessions = 0
    for a in today_activities:
        load = a.get("icu_training_load")
        if isinstance(load, (int, float)):
            today_load += max(0, float(load))
        secs = a.get("moving_time") or a.get("elapsed_time") or 0
        if isinstance(secs, (int, float)):
            today_minutes += max(0, float(secs)) / 60.0
        try:
            family = classify_training_family(a)
            if is_hard_training_family(family):
                hard_sessions += 1
        except Exception:
            pass

    load_cost = min(40, today_load * 0.30)
    duration_cost = min(12, max(0, today_minutes - 45) * 0.045)
    session_cost = max(0, len(today_activities) - 1) * 5
    hard_cost = hard_sessions * 5
    spent = min(62, load_cost + duration_cost + session_cost + hard_cost)

    score = max(5, min(100, round(morning - spent)))
    if score >= 72:
        label, zone = "Charged", "green"
    elif score >= 45:
        label, zone = "Available", "grey"
    elif score >= 25:
        label, zone = "Used", "orange"
    else:
        label, zone = "Drained", "red"

    theta = math.pi - (score / 100.0) * math.pi
    marker_radius = 87
    marker_x = round(100 + marker_radius * math.cos(theta), 1)
    marker_y = round(95 - marker_radius * math.sin(theta), 1)

    return {
        "energy_score": score, "energy_label": label, "energy_zone": zone,
        "marker_x": marker_x, "marker_y": marker_y,
        "energy_morning_score": morning,
        "energy_today_load": round(today_load),
        "energy_today_minutes": round(today_minutes),
        "energy_today_sessions": len(today_activities),
        "energy_spent": round(spent),
        "energy_sleep_quality": sleep_quality,
    }

def sleep_quality_details(value):
    """Intervals.icu sleepQuality: 1=Excellent, 2=Good, 3=Average, 4=Poor."""
    try:
        q = int(float(value))
    except (TypeError, ValueError):
        return "Q–", "No quality data", "qna"
    labels = {1: "Excellent", 2: "Good", 3: "Average", 4: "Poor"}
    q = max(1, min(4, q))
    return f"Q{q}", labels[q], f"q{q}"


def compute_race_readiness(form_zone, fatigue_zone, sleep_quality, personal_baselines):
    """0-100 readiness with a concise explanation; detailed baselines live elsewhere in the UI."""
    score = 50
    signals = []
    score += {"green": 18, "grey": 0, "red": -18}.get(form_zone, 0)
    score += {"green": 15, "grey": 0, "red": -15}.get(fatigue_zone, 0)

    # Sleep quality has deliberate weight. A Q1/Q2 night is meaningful even when
    # duration is modestly below the weekday target.
    if sleep_quality == 1:
        score += 12
    elif sleep_quality == 2:
        score += 9
    elif sleep_quality == 3:
        score -= 3; signals.append((2, "sleep quality average"))
    elif sleep_quality == 4:
        score -= 10; signals.append((3, "sleep quality poor"))

    pb = personal_baselines or {}
    hrv, rhr, sleep, spo2 = (pb.get(k, {}) for k in ("hrv", "rhr", "sleep", "spo2"))

    if hrv.get("status") == "Within baseline": score += 6
    elif hrv.get("status") == "Above baseline": score += 5
    elif hrv.get("status") == "Below baseline":
        score += -9 if hrv.get("color") == "red" else -4
        signals.append((3 if hrv.get("color") == "red" else 2, "HRV below personal range"))

    if rhr.get("status") == "Within baseline": score += 4
    elif rhr.get("status") == "Above baseline":
        score += -8 if rhr.get("color") == "red" else -3
        signals.append((3 if rhr.get("color") == "red" else 2, "resting HR elevated"))

    if sleep.get("color") == "green":
        score += 4
    elif sleep.get("color") == "grey":
        if sleep_quality not in (1, 2):
            score -= 3; signals.append((1, "sleep slightly short"))
    elif sleep.get("color") == "red":
        if sleep_quality in (1, 2):
            score -= 3; signals.append((1, "sleep short but quality good"))
        else:
            score -= 8; signals.append((3, "sleep well below target"))

    if spo2.get("status") != "No current data":
        if spo2.get("color") == "green": score += 2
        elif spo2.get("color") == "red":
            score -= 5; signals.append((2, "SpO2 below usual level"))

    score = max(0, min(100, round(score)))
    signals.sort(key=lambda x: x[0], reverse=True)
    if signals:
        reason = " · ".join(text for _, text in signals[:3])
    elif form_zone == "green" and fatigue_zone == "green":
        reason = "Load balance and recovery signals are supportive."
    else:
        reason = "Recovery signals are broadly stable."

    if score >= 70: return score, "Race Ready", "green", reason
    if score <= 40: return score, "Recovery Bias", "red", reason
    return score, "Train Smart", "grey", reason

def compute_metrics(wellness, form_thresholds=None, fatigue_thresholds=None):
    sorted_wellness = sorted(wellness, key=lambda w: w.get("id", ""))
    latest = sorted_wellness[-1] if sorted_wellness else {}

    ctl = latest.get("ctl")
    atl = latest.get("atl")
    sleep_quality = latest.get("sleepQuality")
    sleep_quality_label, sleep_quality_text, sleep_quality_class = sleep_quality_details(sleep_quality)
    latest_sleep_score = latest.get("sleepScore")
    latest_sleep_secs = latest.get("sleepSecs")
    latest_sleep_duration = _fmt_hours(latest_sleep_secs / 3600.0) if latest_sleep_secs else "n/a"
    latest_sleeping_hr = latest.get("avgSleepingHR")
    tsb = round(ctl - atl, 1) if (ctl is not None and atl is not None) else None

    sleep_values = [w["sleepSecs"] / 3600 for w in wellness if w.get("sleepSecs")]
    avg_sleep = round(statistics.mean(sleep_values), 1) if sleep_values else None

    weight_entries = [w for w in sorted_wellness if w.get("weight")]
    latest_weight = weight_entries[-1]["weight"] if weight_entries else None

    readiness_entries = [w for w in sorted_wellness if w.get("readiness") is not None]
    latest_readiness = readiness_entries[-1]["readiness"] if readiness_entries else None

    spo2_entries = [w for w in sorted_wellness if w.get("spO2") is not None]
    latest_spo2 = spo2_entries[-1]["spO2"] if spo2_entries else None

    form_zone = classify_form(tsb, form_thresholds)
    fatigue_zone = classify_fatigue(atl, ctl, fatigue_thresholds)
    personal_baselines = compute_personal_baselines(wellness)
    race_score, race_label, race_zone, race_reason = compute_race_readiness(
        form_zone, fatigue_zone, sleep_quality, personal_baselines
    )

    sleep_delta_min = None
    if isinstance(latest_sleep_secs, (int, float)):
        sleep_delta_min = round(latest_sleep_secs / 60.0 - GARMIN_BASELINES["sleep_minutes"])
    sleep_score_delta = round(latest_sleep_score - GARMIN_BASELINES["sleep_score"]) if isinstance(latest_sleep_score, (int, float)) else None
    spo2_delta = round(latest_spo2 - GARMIN_BASELINES["spo2"], 1) if isinstance(latest_spo2, (int, float)) else None

    return {
        "ctl": round(ctl, 1) if ctl is not None else "n/a",
        "atl": round(atl, 1) if atl is not None else "n/a",
        "tsb": tsb if tsb is not None else "n/a",
        "fitness_zone": classify_fitness_trend(wellness),
        "fatigue_zone": fatigue_zone,
        "form_zone": form_zone,
        "latest_rhr": latest.get("restingHR", "n/a"),
        "latest_hrv": latest.get("hrv", "n/a"),
        "avg_sleep": f"{avg_sleep}h" if avg_sleep is not None else "n/a",
        "avg_sleep_hours": avg_sleep,
        "latest_weight": f"{round(latest_weight, 1)}kg" if latest_weight is not None else "n/a",
        "latest_readiness": round(latest_readiness) if latest_readiness is not None else None,
        "latest_spo2": round(latest_spo2, 1) if latest_spo2 is not None else None,
        "sleep_quality": sleep_quality,
        "sleep_quality_label": sleep_quality_label,
        "sleep_quality_text": sleep_quality_text,
        "sleep_quality_class": sleep_quality_class,
        "latest_sleep_score": round(latest_sleep_score) if latest_sleep_score is not None else None,
        "latest_sleep_duration": latest_sleep_duration,
        "latest_sleeping_hr": round(latest_sleeping_hr) if latest_sleeping_hr is not None else None,
        "sleep_delta_min": sleep_delta_min,
        "sleep_score_delta": sleep_score_delta,
        "spo2_delta": spo2_delta,
        "personal_baselines": personal_baselines,
        "race_readiness_score": race_score,
        "race_readiness_label": race_label,
        "race_readiness_zone": race_zone,
        "race_readiness_css_color": {"green": "green", "red": "red", "grey": "grey-zone"}.get(race_zone, "grey-zone"),
        "race_readiness_reason": race_reason,
    }

def build_data_text(recent_activities, wellness, season_stats, notes=None, feelings=None, best_watts=None, vo2_trend=None):
    lines = ["RECENT ACTIVITIES (last {} days):".format(DAYS_BACK)]
    if not recent_activities:
        lines.append("(no activities found on Intervals.icu for this period)")
    for a in recent_activities:
        duration_sec = a.get("moving_time") or a.get("elapsed_time") or 0
        power = a.get("icu_weighted_avg_watts") or a.get("average_watts") or "n/a"
        lines.append(
            "- {date} | {name} | {type} | {dur} min | load {load} | "
            "power {pwr} | HR {hr} | calories {cal} | Intervals CHO used {cho_used}g | CHO ingested {cho_in}g".format(
                date=a.get("start_date_local", "").replace("T", " ")[:16],
                name=a.get("name", ""),
                type=a.get("type", ""),
                dur=round(duration_sec / 60),
                load=a.get("icu_training_load", "n/a"),
                pwr=power,
                hr=a.get("average_heartrate", "n/a"),
                cal=a.get("calories", "n/a"),
                cho_used=a.get("carbs_used", "n/a"),
                cho_in=a.get("carbs_ingested", "n/a"),
            )
        )

    lines.append("\nSEASON SUMMARY (last {} days, time-in-zone based):".format(SEASON_DAYS_BACK))
    lines.append(
        "- Total training time: {}h | Total load: {} | "
        "Low intensity: {}% | Moderate intensity: {}% | High intensity: {}%".format(
            season_stats["season_hours"], season_stats["season_total_load"],
            season_stats["zone_low_pct"], season_stats["zone_mod_pct"], season_stats["zone_high_pct"],
        )
    )

    if best_watts:
        lines.append("\nREAL POWER CURVE (actual best efforts, last 42 days - use these as the "
                     "ceiling for any power target you prescribe, never exceed them for that "
                     "duration or shorter):")
        for p in best_watts:
            lines.append("- {}: {}W".format(p["label"], p["watts"]))

    if vo2_trend and vo2_trend.get("available"):
        lines.append("\nVO2MAX TREND (MODEL ESTIMATES ONLY - longitudinal context, NOT a measured VO2max and NOT a primary readiness signal):")
        if vo2_trend.get("wearable_current") is not None:
            lines.append("- Wearable / Intervals Wellness: {} ml/kg/min | 28d delta {}".format(
                vo2_trend.get("wearable_current"), vo2_trend.get("wearable_delta28") if vo2_trend.get("wearable_delta28") is not None else "n/a"))
        if vo2_trend.get("performance_current") is not None:
            lines.append("- Intervals 5-min-power estimate: {} ml/kg/min | 28d delta {}".format(
                vo2_trend.get("performance_current"), vo2_trend.get("performance_delta28") if vo2_trend.get("performance_delta28") is not None else "n/a"))
        lines.append("- Trend agreement: {}. Use only as longitudinal performance context; do not let it override health, recovery, availability or recent training.".format(vo2_trend.get("agreement", "n/a")))

    lines.append("\nWELLNESS (last {} days):".format(DAYS_BACK))
    for w in sorted(wellness, key=lambda x: x.get("id", "")):
        line = (
            "- {date} | RHR {rhr} | HRV {hrv} | sleep {sleep}h | CTL {ctl} | ATL {atl}".format(
                date=w.get("id", ""),
                rhr=w.get("restingHR", "n/a"),
                hrv=w.get("hrv", "n/a"),
                sleep=round(w["sleepSecs"] / 3600, 1) if w.get("sleepSecs") else "n/a",
                ctl=round(w["ctl"], 1) if w.get("ctl") is not None else "n/a",
                atl=round(w["atl"], 1) if w.get("atl") is not None else "n/a",
            )
            + " | sleepQ {} | sleepScore {} | sleepingHR {} | SpO2 {} | wearableReadiness {}".format(
                ("Q" + str(w.get("sleepQuality"))) if w.get("sleepQuality") is not None else "n/a",
                round(w.get("sleepScore")) if w.get("sleepScore") is not None else "n/a",
                round(w.get("avgSleepingHR")) if w.get("avgSleepingHR") is not None else "n/a",
                round(w.get("spO2"), 1) if w.get("spO2") is not None else "n/a",
                round(w.get("readiness")) if w.get("readiness") is not None else "n/a",
            )
        )
        if w.get("weight"):
            line += " | weight {}kg".format(round(w["weight"], 1))
        if w.get("comments"):
            line += " | note: {}".format(w["comments"])
        lines.append(line)

    if notes:
        lines.append("\nCOACH NOTES (things the athlete has told you before, most recent last):")
        for n in notes:
            lines.append("- {date}: {text}".format(date=n.get("date", ""), text=n.get("text", "")))

    if feelings:
        lines.append("\nSELF-REPORTED DAILY LOG (1=bad, 10=amazing; context matters):")
        for f in feelings[-20:]:
            lines.append(
                "- {date} {time} | {value}/10 | {phase} | status {status} | sessions {sessions} | load {load} | note {note}".format(
                    date=f.get("date", ""), time=f.get("time", ""), value=f.get("value", ""), phase=f.get("phase", ""),
                    status=f.get("status", "NORMAL"), sessions=f.get("sessions", "n/a"), load=f.get("load", "n/a"), note=f.get("note") or "none"
                )
            )

    return "\n".join(lines)



def get_rome_now():
    """Current wall-clock time for the athlete/coach, independent of Render's server timezone."""
    return datetime.now(ROME_TZ)


def parse_local_activity_datetime(value):
    if not value:
        return None
    try:
        return datetime.fromisoformat(str(value).replace("Z", "+00:00")).replace(tzinfo=None)
    except (ValueError, TypeError):
        return None


def get_clock_preview(now=None):
    now = now or get_rome_now()
    hour = now.hour
    if hour < 12:
        phase = "Morning window · before 12:00 PM"
    elif hour < 17:
        phase = "Between sessions · 12:00 PM–05:00 PM"
    else:
        phase = "Evening window · after 05:00 PM"
    return {"time": now.strftime("%I:%M %p"), "time_clock": now.strftime("%I:%M"), "time_period": now.strftime("%p"), "phase": phase}


def build_coach_clock(recent_activities, now=None, planning_context=None):
    """Deterministic session awareness with V10 health/availability/event constraints.

    Intervals activities determine what is already done. Structured V10 planning
    items determine what is allowed. Blackout dates are removed before Claude
    ever sees a slot; no-intensity dates remain but carry a hard restriction.
    """
    now = now or get_rome_now()
    planning_context = planning_context or build_planning_context(now)
    today = now.date()
    today_iso = today.isoformat()
    today_acts = []
    for activity in recent_activities:
        start_raw = activity.get("start_date_local") or ""
        if start_raw[:10] != today_iso:
            continue
        dt = parse_local_activity_datetime(start_raw)
        hour = dt.hour if dt else None
        today_acts.append({
            "name": activity.get("name") or activity.get("type") or "Activity",
            "hour": hour,
            "time": dt.strftime("%I:%M %p") if dt else "time n/a",
        })

    am_done = any(a["hour"] is not None and a["hour"] < 12 for a in today_acts)
    pm_done = any(a["hour"] is not None and a["hour"] >= 17 for a in today_acts)
    blocked_today = today_iso in set(planning_context.get("blackout_dates") or [])
    no_intensity_today = today_iso in set(planning_context.get("no_intensity_dates") or [])
    health = planning_context.get("health_override")

    if health:
        phase = "HEALTH OVERRIDE"
        headline = "Health context has priority"
        explanation = (
            f'{health.get("kind")} is active through {health.get("until")}. '
            "THE LAB will not treat falling training load as tapering/peaking and will only expose slots compatible with the active restriction."
        )
    elif blocked_today:
        phase = "NO TRAINING"
        headline = "Today is blocked from training"
        explanation = "A structured availability rule removes today from Upcoming Sessions before the coach is called."
    elif no_intensity_today:
        phase = "RESTRICTED"
        headline = "No-intensity restriction active"
        explanation = "Today remains trainable, but Python will enforce easy aerobic work only even if the AI suggests intensity."
    elif now.hour < 12:
        phase = "AM WINDOW"
        headline = "Morning session decision"
        explanation = "The morning training window is still open. A logged Intervals.icu activity counts as completed immediately."
    elif now.hour < 17:
        phase = "BETWEEN SESSIONS"
        headline = "Morning checked · evening next"
        explanation = "The morning window has passed. THE LAB checks the real activity log, then plans from the evening slot onward."
    else:
        if pm_done:
            phase = "DAY COMPLETE"
            headline = "Today's two-a-day is closed"
            explanation = "The evening activity is already logged, so planning moves forward rather than repeating today's work."
        else:
            phase = "PM WINDOW"
            headline = "Evening session decision"
            explanation = "It is after 05:00 PM. If no PM activity is logged, the current evening slot is the next decision."

    if now.hour < 12:
        am_status = "DONE" if am_done else ("BLOCKED" if blocked_today else "OPEN")
        am_class = "done" if am_done else ("missed" if blocked_today else "open")
        pm_status = "DONE" if pm_done else ("BLOCKED" if blocked_today else ("EASY ONLY" if no_intensity_today else "UPCOMING"))
        pm_class = "done" if pm_done else ("missed" if blocked_today else "upcoming")
    elif now.hour < 17:
        am_status = "DONE" if am_done else ("BLOCKED" if blocked_today else "NO ACTIVITY")
        am_class = "done" if am_done else "missed"
        pm_status = "DONE" if pm_done else ("BLOCKED" if blocked_today else ("EASY ONLY" if no_intensity_today else "UPCOMING"))
        pm_class = "done" if pm_done else ("missed" if blocked_today else "upcoming")
    else:
        am_status = "DONE" if am_done else ("BLOCKED" if blocked_today else "NO ACTIVITY")
        am_class = "done" if am_done else "missed"
        pm_status = "DONE" if pm_done else ("BLOCKED" if blocked_today else ("EASY ONLY" if no_intensity_today else "OPEN"))
        pm_class = "done" if pm_done else ("missed" if blocked_today else "open")

    blackout = set(planning_context.get("blackout_dates") or [])
    easy_only = set(planning_context.get("no_intensity_dates") or [])
    race_by_date = planning_context.get("race_by_date") or {}
    candidates = []
    race_added = set()

    def add_candidate(slot_date, period):
        ds = slot_date.isoformat()
        # Health/availability restrictions outrank events. A race inside a blackout
        # is not a valid session; a race inside NO_INTENSITY is not allowed to
        # override the restriction and the day remains easy-only.
        if ds in blackout:
            return
        race = race_by_date.get(ds)
        if race and ds not in easy_only:
            if ds not in race_added:
                candidates.append((slot_date, "RACE", race))
                race_added.add(ds)
            return
        candidates.append((slot_date, period, None))

    if now.hour < 12 and not am_done:
        add_candidate(today, "AM")
    if not pm_done:
        add_candidate(today, "PM")

    d = today + timedelta(days=1)
    guard = 0
    while len(candidates) < 3 and guard < 120:
        add_candidate(d, "AM")
        if len(candidates) < 3:
            add_candidate(d, "PM")
        d += timedelta(days=1)
        guard += 1

    next_slots = []
    for slot_date, period, race in candidates[:3]:
        ds = slot_date.isoformat()
        if slot_date == today:
            day_word = "Today"
        elif slot_date == today + timedelta(days=1):
            day_word = "Tomorrow"
        else:
            day_word = slot_date.strftime("%A")
        if period == "RACE":
            label = f'{day_word} · RACE · {race.get("title") or "Priority event"}'
            window = "priority event"
            restriction = "RACE"
        else:
            window = "before 12:00 PM" if period == "AM" else "after 05:00 PM"
            label = f"{day_word} · {period} · {window}"
            restriction = "NO_INTENSITY" if ds in easy_only else "NONE"
        next_slots.append({
            "date": ds, "period": period, "window": window, "label": label,
            "restriction": restriction,
            "restriction_until": next((i.get("end_date") for i in planning_context.get("upcoming_items", []) if i.get("restriction_type") == restriction and _date_in_item(i, slot_date)), None) if restriction == "NO_INTENSITY" else None,
            "is_race": period == "RACE",
            "event_title": race.get("title") if race else None,
        })

    acts_text = ", ".join(f'{a["time"]} {a["name"]}' for a in today_acts)
    minutes = now.hour * 60 + now.minute
    day_progress = round(minutes / 1440 * 100, 1)
    clock_angle = (day_progress / 100.0) * 2 * math.pi - (math.pi / 2)
    return {
        "iso": now.isoformat(), "time": now.strftime("%I:%M %p"), "time_clock": now.strftime("%I:%M"), "time_period": now.strftime("%p"), "timezone": now.tzname() or "Europe/Rome",
        "date_label": now.strftime("%d/%m/%Y"), "phase": phase, "headline": headline, "explanation": explanation,
        "am_done": am_done, "pm_done": pm_done, "am_status": am_status, "pm_status": pm_status,
        "am_status_class": am_class, "pm_status_class": pm_class, "today_activity_count": len(today_acts),
        "today_activities_text": acts_text, "next_slots": next_slots,
        "next_slot_label": next_slots[0]["label"] if next_slots else "No available training slot",
        "day_progress": day_progress,
        "marker_x": round(90 + 68 * math.cos(clock_angle), 1),
        "marker_y": round(90 + 68 * math.sin(clock_angle), 1),
        "planning_summary": planning_context.get("summary", "Training as planned"),
    }


def coach_clock_text(clock):
    slots = "\n".join(
        f'{i+1}. {s["label"]} ({s["date"]}) | restriction {s.get("restriction", "NONE")}'
        for i, s in enumerate(clock.get("next_slots") or [])
    )
    activities = clock.get("today_activities_text") or "none logged yet"
    return (
        "COACH CLOCK (authoritative timing context):\n"
        f'- Snapshot requested at {clock["time"]} {clock["timezone"]} on {clock["date_label"]}.\n'
        f'- Current phase: {clock["phase"]}.\n'
        f'- Planning state: {clock.get("planning_summary", "Training as planned")}.\n'
        f'- Morning slot status: {clock["am_status"]}. Evening slot status: {clock["pm_status"]}.\n'
        f'- Activities already logged today: {activities}.\n'
        "- The next three VALID decision slots after hard Python filtering are:\n"
        f"{slots}\n"
        "Never prescribe a removed/blocked slot. NO_INTENSITY means easy aerobic/recovery only. RACE means the event itself, not an extra workout."
    )



def classify_training_family(activity):
    """Classify a completed activity into a coaching family using its title first,
    then time-in-zone as a conservative fallback. This is intentionally broad: the
    goal is to stop Claude from accidentally repeating the same quality stimulus,
    not to pretend we can perfectly reverse-engineer every Zwift workout."""
    name = str(activity.get("name") or "").lower()
    compact = name.replace("-", " ").replace("_", " ")

    keyword_groups = [
        ("Recovery", ("recovery", "recuper", "easy spin", "scarico")),
        ("Sprint / Neuromuscular", ("sprint", "neuromus", "anaerobic", "anaerobico")),
        ("VO2max", ("vo2", "vo₂", "vo 2", "max aerobic")),
        ("Over-Under", ("over under", "overunder", "o&u", "over / under")),
        ("Threshold / TTE", ("tte", "threshold", "soglia", "ftp", "time to exhaustion")),
        ("Sweet Spot", ("sweet spot", "sweetspot")),
        ("Tempo", ("tempo", "z3", "zone 3")),
        ("Endurance / Z2", ("z2", "zone 2", "endurance", "aerobic", "endurance ride")),
    ]
    for label, keys in keyword_groups:
        if any(k in compact for k in keys):
            return label

    zone_times = activity.get("icu_zone_times") or []
    if zone_times:
        try:
            secs = [float(z.get("secs") or 0) for z in zone_times]
            low, mod, high = bucket_zone_seconds(secs)
            total = low + mod + high
            if total > 0:
                high_pct = 100 * high / total
                mod_pct = 100 * mod / total
                if high_pct >= 15:
                    return "High Intensity / Mixed"
                if mod_pct >= 30:
                    return "Tempo / Threshold Mixed"
                if low / total >= 0.75:
                    return "Endurance / Z2"
        except (TypeError, ValueError):
            pass
    return "Other / Mixed"


def is_hard_training_family(family):
    f = (family or "").lower()
    return any(k in f for k in (
        "vo2", "threshold", "tte", "over-under", "sprint", "neuromuscular",
        "high intensity", "tempo / threshold"
    ))


def build_week_memory(recent_activities, now=None):
    """Reconstruct the current Monday→now training week directly from Intervals.icu.

    This is fresh on every snapshot, so it survives deploys and does not rely on
    Claude remembering what happened yesterday.
    """
    now = now or get_rome_now()
    today = now.date()
    monday = today - timedelta(days=today.weekday())
    items = []

    for activity in recent_activities:
        raw = activity.get("start_date_local") or ""
        dt = parse_local_activity_datetime(raw)
        if not dt:
            continue
        d = dt.date()
        if d < monday or d > today:
            continue
        # If an activity is timestamped later today than the snapshot, ignore it.
        if d == today and dt.time() > now.replace(tzinfo=None).time():
            continue

        family = classify_training_family(activity)
        duration_sec = activity.get("moving_time") or activity.get("elapsed_time") or 0
        item = {
            "date": d.isoformat(),
            "day": d.strftime("%A"),
            "day_short": d.strftime("%a"),
            "time": dt.strftime("%I:%M %p"),
            "name": activity.get("name") or activity.get("type") or "Activity",
            "family": family,
            "family_short": family.replace("Endurance / ", "").replace(" / Mixed", ""),
            "duration_min": round(duration_sec / 60) if duration_sec else None,
            "load": activity.get("icu_training_load"),
            "hard": is_hard_training_family(family),
        }
        items.append(item)

    items.sort(key=lambda x: (x["date"], x["time"]))
    hard_items = [x for x in items if x["hard"]]
    hard_families = []
    for x in hard_items:
        if x["family"] not in hard_families:
            hard_families.append(x["family"])

    # Days since the most recent hard session is useful spacing information for Claude.
    last_hard = hard_items[-1] if hard_items else None
    days_since_last_hard = None
    if last_hard:
        days_since_last_hard = (today - date.fromisoformat(last_hard["date"])).days

    return {
        "week_start": monday.isoformat(),
        "week_end": today.isoformat(),
        "activities": items,
        "hard_count": len(hard_items),
        "hard_families": hard_families,
        "hard_summary": ", ".join(hard_families),
        "last_hard": last_hard,
        "days_since_last_hard": days_since_last_hard,
    }


def week_memory_text(memory):
    if not memory or not memory.get("activities"):
        return (
            "CURRENT WEEK TRAINING HISTORY (Monday to snapshot time):\n"
            "- No completed activities found yet this week."
        )

    lines = ["CURRENT WEEK TRAINING HISTORY (Monday to snapshot time — authoritative):"]
    for a in memory["activities"]:
        dur = f'{a["duration_min"]} min' if a.get("duration_min") is not None else "duration n/a"
        load = a.get("load") if a.get("load") is not None else "n/a"
        quality = "HARD/QUALITY" if a.get("hard") else "easy/moderate"
        lines.append(
            f'- {a["day"]} {a["date"]} {a["time"]} | {a["family"]} | {quality} | '
            f'{dur} | load {load} | {a["name"]}'
        )
    if memory.get("last_hard"):
        lh = memory["last_hard"]
        lines.append(
            f'- Most recent hard/quality stimulus: {lh["family"]} on {lh["day"]} {lh["date"]} '
            f'({memory.get("days_since_last_hard")} day(s) ago).'
        )
    lines.append(
        "Use this history before prescribing the next sessions. Do not repeat the same hard workout family "
        "simply because it fits the next slot. In particular, avoid another TTE/threshold, VO2max, Over-Under "
        "or sprint/neuromuscular stimulus too close to the same family already completed. Prefer complementary "
        "work and adequate spacing. A repeat is allowed only when there is a clear coaching reason, and that "
        "reason must be stated explicitly in the session rationale."
    )
    return "\n".join(lines)


def intensity_class(value):
    v = (value or "").lower()
    if "vo2" in v or "vo₂" in v or "anaer" in v:
        return "vo2"
    if "threshold" in v or "soglia" in v:
        return "threshold"
    if "tempo" in v or "sweet" in v:
        return "tempo"
    if "recover" in v or "easy" in v:
        return "recovery"
    return "endurance"


def normalize_next_sessions(raw_sessions, clock):
    raw_sessions = raw_sessions if isinstance(raw_sessions, list) else []
    normalized = []
    for idx, slot in enumerate(clock.get("next_slots") or []):
        raw = raw_sessions[idx] if idx < len(raw_sessions) and isinstance(raw_sessions[idx], dict) else {}

        if slot.get("is_race"):
            normalized.append({
                "slot": slot["label"], "date": slot.get("date"), "period": "RACE",
                "title": slot.get("event_title") or "Race day", "duration": "Priority event",
                "intensity": "Race", "intensity_class": "vo2",
                "main_set": "Race day. No additional training session is prescribed for this slot.",
                "why": "This registered race/event has priority over routine training.",
                "restriction": "RACE",
            })
            continue

        if slot.get("restriction") == "NO_INTENSITY":
            until = slot.get("restriction_until") or "the active restriction end date"
            normalized.append({
                "slot": slot["label"], "date": slot.get("date"), "period": slot.get("period"),
                "title": "Aerobic endurance · restriction active", "duration": str(raw.get("duration") or "Up to 60 min"),
                "intensity": "Z1–Z2 only", "intensity_class": "recovery",
                "main_set": "Easy aerobic riding only. No threshold, VO₂, over-under, sprint or other intentional intensity.",
                "why": f"Python-enforced no-intensity restriction is active through {until}; health/availability constraints outrank the AI prescription.",
                "restriction": "NO_INTENSITY",
            })
            continue

        intensity = str(raw.get("intensity") or ("Endurance" if slot.get("period") == "AM" else "Training"))
        normalized.append({
            "slot": slot["label"], "date": slot.get("date"), "period": slot.get("period"),
            "title": str(raw.get("title") or ("Aerobic endurance" if slot.get("period") == "AM" else "Coach-selected session")),
            "duration": str(raw.get("duration") or "Up to 60 min"), "intensity": intensity,
            "intensity_class": intensity_class(intensity),
            "main_set": str(raw.get("main_set") or "See coach recommendation."),
            "why": str(raw.get("why") or "Selected from current recovery, load, timing and event context."),
            "restriction": "NONE",
        })
    return normalized



def _nutrition_number(value):
    try:
        value = float(value)
    except (TypeError, ValueError):
        return None
    return value if math.isfinite(value) else None


def _activity_local_dt(activity):
    raw = str(activity.get("start_date_local") or "")
    if not raw:
        return None
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        try:
            return datetime.strptime(raw[:16], "%Y-%m-%dT%H:%M")
        except ValueError:
            return None


def build_weight_context(season_wellness, now=None):
    """Return a dated weight value and an explicit confidence state.

    Precise carb-loading totals in grams are never calculated from a stale or
    missing weight. The g/kg reference can still be shown, but THE LAB asks for
    a fresh body weight before turning it into an apparently precise daily total.
    """
    now = now or get_rome_now()
    entries = []
    for w in season_wellness or []:
        kg = _nutrition_number(w.get("weight"))
        ds = str(w.get("id") or "")[:10]
        if kg is None or kg <= 0:
            continue
        try:
            d = date.fromisoformat(ds)
        except ValueError:
            continue
        entries.append((d, kg))
    if not entries:
        return {
            "kg": None, "date": None, "age_days": None, "status": "MISSING",
            "needs_update": True, "label": "No weight in the current data window",
            "detail": "Update body weight before calculating a precise carb-loading total.",
        }
    d, kg = max(entries, key=lambda x: x[0])
    age = max(0, (now.date() - d).days)
    current_days = ATHLETE_FUELING_PROFILE["weight_current_days"]
    aging_days = ATHLETE_FUELING_PROFILE["weight_aging_days"]
    if age <= current_days:
        status, needs_update = "CURRENT", False
        detail = f"{kg:.1f} kg · measured {age} day(s) ago."
    elif age <= aging_days:
        status, needs_update = "AGING", False
        detail = f"{kg:.1f} kg · {age} days old. Usable for context, but refresh it before race week if practical."
    else:
        status, needs_update = "STALE", True
        detail = f"{kg:.1f} kg · {age} days old. Update weight before a precise carb-loading total is calculated."
    return {
        "kg": round(kg, 1), "date": d.isoformat(), "age_days": age,
        "status": status, "needs_update": needs_update,
        "label": f"{kg:.1f} kg · {status}", "detail": detail,
    }


def assess_intervals_cho(activity):
    """Sanity-check Intervals.icu's estimated carbohydrate utilisation.

    Intervals exposes carbs_used and carbs_ingested. carbs_used is modelled, not
    directly measured. Known model limitations make very short/long sessions and
    impossible energy relationships unsuitable for quantitative glycogen context.
    """
    used = _nutrition_number(activity.get("carbs_used"))
    ingested = _nutrition_number(activity.get("carbs_ingested")) or 0.0
    kcal = _nutrition_number(activity.get("calories"))
    secs = _nutrition_number(activity.get("moving_time") or activity.get("elapsed_time")) or 0.0
    mins = secs / 60.0
    result = {
        "used_g": round(used, 1) if used is not None else None,
        "ingested_g": round(max(0.0, ingested), 1),
        "valid": False, "reason": "No Intervals CHO-use estimate", "duration_min": round(mins, 1),
    }
    if used is None or used < 0:
        return result
    if mins < 30 or mins > 90:
        result["reason"] = "Low confidence: Intervals CHO model is least reliable outside roughly 30–90 min"
        return result
    if kcal is not None and kcal > 0 and used * 4.0 > kcal * 1.10:
        result["reason"] = "Low confidence: estimated CHO energy exceeds total session calories"
        return result
    result["valid"] = True
    result["reason"] = "Accepted as a model estimate after duration/energy sanity checks"
    return result


def build_metabolic_context(recent_activities, season_wellness, planning_context, now=None):
    """Build deterministic energy/glycogen/race context before the AI is called."""
    now = now or get_rome_now()
    planning_context = planning_context or {}
    local_now = now.replace(tzinfo=None) if now.tzinfo else now
    since36 = local_now - timedelta(hours=36)
    since48 = local_now - timedelta(hours=48)
    acts36, acts48 = [], []
    for a in recent_activities or []:
        dt = _activity_local_dt(a)
        if not dt:
            continue
        if dt.tzinfo:
            dt = dt.astimezone(ROME_TZ).replace(tzinfo=None)
        if dt >= since48:
            acts48.append(a)
        if dt >= since36:
            acts36.append(a)

    kcal36 = round(sum(_nutrition_number(a.get("calories")) or 0 for a in acts36))
    kcal48 = round(sum(_nutrition_number(a.get("calories")) or 0 for a in acts48))
    load48 = round(sum(_nutrition_number(a.get("icu_training_load")) or 0 for a in acts48), 1)
    hard48 = sum(1 for a in acts48 if is_hard_training_family(classify_training_family(a)))

    cho_checks = [assess_intervals_cho(a) for a in acts48]
    valid_cho = [c for c in cho_checks if c["valid"]]
    invalid_cho = [c for c in cho_checks if c.get("used_g") is not None and not c["valid"]]
    used48 = round(sum(c["used_g"] or 0 for c in valid_cho), 1) if valid_cho else None
    ingested48 = round(sum(c["ingested_g"] or 0 for c in valid_cho), 1) if valid_cho else None
    exercise_gap = round(max(0.0, (used48 or 0) - (ingested48 or 0)), 1) if valid_cho else None

    score = 0
    if kcal48 >= 1400: score += 2
    elif kcal48 >= 700: score += 1
    if load48 >= 140: score += 2
    elif load48 >= 70: score += 1
    if hard48 >= 2: score += 2
    elif hard48 == 1: score += 1
    if exercise_gap is not None:
        if exercise_gap >= 160: score += 2
        elif exercise_gap >= 80: score += 1
    glycogen_pressure = "HIGH" if score >= 5 else ("MODERATE" if score >= 2 else "LOW")

    weight = build_weight_context(season_wellness, now)
    race = planning_context.get("next_race") or None
    health = planning_context.get("health_override")
    if not race:
        race_state = "OFF"
        race_detail = "No upcoming race is registered in the active planning horizon."
    elif health or race.get("conflict"):
        race_state = "PAUSED"
        race_detail = "Health/restriction context outranks race-prep nutrition until the conflict is resolved."
    else:
        days = int(race.get("days_away") or 0)
        if days <= 0:
            race_state = "RACE DAY"
            race_detail = "Race day: prioritize pre-race availability and the athlete's practised ~100 g CHO/h race fueling strategy."
        elif days <= ATHLETE_FUELING_PROFILE["carb_loading_active_days"]:
            race_state = "ACTIVE"
            race_detail = "Carbohydrate-loading relevance is high: raise daily carbohydrate availability rather than judging recovery meal-by-meal."
        elif days <= ATHLETE_FUELING_PROFILE["carb_loading_approaching_days"]:
            race_state = "APPROACHING"
            race_detail = "Race carbohydrate-loading window is approaching; begin protecting glycogen availability while taper volume falls."
        else:
            race_state = "NOT YET"
            race_detail = f"Race is {days} days away; deliberate carbohydrate loading is not active yet."

    gkg_low = ATHLETE_FUELING_PROFILE["carb_loading_gkg_low"]
    gkg_high = ATHLETE_FUELING_PROFILE["carb_loading_gkg_high"]
    total_range = None
    if race_state == "ACTIVE" and weight.get("kg") and not weight.get("needs_update"):
        lo = int(round(weight["kg"] * gkg_low / 10.0) * 10)
        hi = int(round(weight["kg"] * gkg_high / 10.0) * 10)
        total_range = f"~{lo}–{hi} g CHO/day"

    return {
        "kcal_36h": kcal36, "kcal_48h": kcal48, "load_48h": load48,
        "hard_sessions_48h": hard48, "glycogen_pressure": glycogen_pressure,
        "cho_used_48h": used48, "cho_ingested_48h": ingested48,
        "exercise_cho_gap_48h": exercise_gap, "cho_valid_count": len(valid_cho),
        "cho_low_confidence_count": len(invalid_cho), "weight": weight,
        "race_strategy": {
            "state": race_state, "detail": race_detail,
            "title": race.get("title") if race else None,
            "date": race.get("start_date") if race else None,
            "days_away": race.get("days_away") if race else None,
            "race_fueling": f'~{ATHLETE_FUELING_PROFILE["race_g_per_hour"]} g CHO/h',
            "loading_gkg": f"{gkg_low:.0f}–{gkg_high:.0f} g/kg/day reference" if race_state in ("ACTIVE", "APPROACHING") else None,
            "loading_total": total_range,
            "weight_update_required": bool(race_state == "ACTIVE" and weight.get("needs_update")),
        },
    }


def metabolic_context_text(context):
    c = context or {}
    r = c.get("race_strategy") or {}
    w = c.get("weight") or {}
    used = c.get("cho_used_48h")
    ing = c.get("cho_ingested_48h")
    gap = c.get("exercise_cho_gap_48h")
    cho_line = "No reliable Intervals CHO-use estimate in the last 48h."
    if used is not None:
        cho_line = f"Accepted Intervals estimate: {used} g CHO used; {ing or 0} g recorded ingested; exercise-only gap {gap} g."
    return (
        "NUTRITION / GLYCOGEN CONTEXT (Python-derived; use for reasoning, do not invent glycogen stores):\n"
        f'- Athlete fueling baseline: race ~{ATHLETE_FUELING_PROFILE["race_g_per_hour"]} g CHO/h; hard outdoor training ~{ATHLETE_FUELING_PROFILE["hard_outdoor_g_per_hour"]} g/h; indoor training usually 0 g/h during the session, with carbohydrate handled in recovery.\n'
        f'- Completed training last 36h: {c.get("kcal_36h", 0)} kcal. Last 48h: {c.get("kcal_48h", 0)} kcal, load {c.get("load_48h", 0)}, hard/quality sessions {c.get("hard_sessions_48h", 0)}.\n'
        f'- Glycogen replenishment pressure: {c.get("glycogen_pressure", "LOW")}. {cho_line} Low-confidence CHO estimates ignored: {c.get("cho_low_confidence_count", 0)}.\n'
        f'- Weight confidence: {w.get("status", "MISSING")} | {w.get("detail", "No weight available")}.\n'
        f'- Race carb strategy: {r.get("state", "OFF")} | {r.get("detail", "")}' + (f' | {r.get("loading_gkg")}' if r.get("loading_gkg") else '') + (f' | {r.get("loading_total")}' if r.get("loading_total") else '') + "\n"
        "- CRITICAL INTERPRETATION RULE: keep SESSION DEMAND separate from RECOVERY NEED. An easy/recovery ride remains LOW demand even when recent training or race preparation justifies more carbohydrate afterward. Never relabel an easy ride as hard to justify a higher CHO target.\n"
        "- If carb loading is ACTIVE and weight is stale/missing, explicitly ask the athlete to update weight before giving a precise total grams/day target."
    )


def classify_upcoming_session_demand(session_item):
    """Classify the prescribed session from structured fields, never main-set prose."""
    restriction = str(session_item.get("restriction") or "").upper()
    intensity_cls = str(session_item.get("intensity_class") or "endurance").lower()
    title = str(session_item.get("title") or "").lower()
    intensity = str(session_item.get("intensity") or "").lower()
    short_text = f"{title} {intensity}"
    if restriction == "RACE" or str(session_item.get("period") or "").upper() == "RACE":
        kind = "RACE"
    elif restriction == "NO_INTENSITY" or intensity_cls == "recovery":
        kind = "RECOVERY"
    elif intensity_cls == "endurance":
        kind = "HEAT" if any(k in short_text for k in ("heat", "thermal", "hot room", "caldo")) else "ENDURANCE"
    elif intensity_cls == "tempo":
        kind = "TEMPO"
    elif intensity_cls == "threshold":
        kind = "THRESHOLD"
    elif intensity_cls == "vo2":
        kind = "VO2"
    else:
        kind = "ENDURANCE"
    demand = {
        "RECOVERY": "LOW", "ENDURANCE": "LOW–MODERATE", "HEAT": "MODERATE",
        "TEMPO": "MODERATE–HIGH", "THRESHOLD": "HIGH", "VO2": "HIGH", "RACE": "VERY HIGH",
    }[kind]
    explicit_outdoor = any(k in short_text for k in ("outdoor", "road", "outside", "granfondo", "gran fondo", "race"))
    explicit_indoor = any(k in short_text for k in ("indoor", "zwift", "trainer"))
    environment = "OUTDOOR" if (kind == "RACE" or explicit_outdoor) else ("INDOOR" if explicit_indoor else ATHLETE_FUELING_PROFILE["default_training_environment"])
    return {"kind": kind, "demand": demand, "environment": environment}


def _session_clock(session_item):
    ds = str(session_item.get("date") or "")[:10]
    try:
        d = date.fromisoformat(ds)
    except ValueError:
        return None
    period = str(session_item.get("period") or "").upper()
    hour = 9 if period == "RACE" else (8 if period == "AM" else 18)
    return datetime.combine(d, datetime.min.time()).replace(hour=hour)


def _post_workout_range(kind, metabolic_context, next_gap_hours=None):
    base = {
        "RECOVERY": (0, 20), "ENDURANCE": (0, 30), "HEAT": (30, 40),
        "TEMPO": (40, 50), "THRESHOLD": (50, 60), "VO2": (50, 60), "RACE": (60, 90),
    }[kind]
    boost = 0
    pressure = str((metabolic_context or {}).get("glycogen_pressure") or "LOW")
    if pressure == "HIGH": boost += 15
    elif pressure == "MODERATE": boost += 5
    if next_gap_hours is not None:
        if next_gap_hours <= 10: boost += 10
        elif next_gap_hours <= 20: boost += 5
    race_state = str(((metabolic_context or {}).get("race_strategy") or {}).get("state") or "OFF")
    if race_state == "ACTIVE": boost += 20
    elif race_state == "APPROACHING": boost += 10
    caps = {"RECOVERY": 60, "ENDURANCE": 60, "HEAT": 70, "TEMPO": 80, "THRESHOLD": 90, "VO2": 90, "RACE": 100}
    lo = min(caps[kind], base[0] + boost)
    hi = min(caps[kind], base[1] + boost)
    lo = int(round(lo / 10.0) * 10)
    hi = int(round(hi / 10.0) * 10)
    if hi <= 20:
        return "0–20 g CHO", "LIGHT"
    if lo == hi:
        return f"~{hi} g CHO", "MODERATE" if hi < 60 else "HIGH"
    return f"{lo}–{hi} g CHO", "MODERATE" if hi < 60 else "HIGH"


def build_nutrition_plan(next_sessions, metabolic_context, now=None):
    """Structured Nutrition Engine: demand != recovery need.

    No keyword scan of main_set is allowed here. Session demand comes from the
    normalized intensity class/restriction; recent calories, accepted Intervals
    CHO estimates, race proximity, weight freshness and next-session spacing then
    alter recovery need without changing what the workout actually is.
    """
    now = now or get_rome_now()
    sessions = list(next_sessions or [])
    plans = []
    for idx, session_item in enumerate(sessions):
        cls = classify_upcoming_session_demand(session_item)
        kind, demand, environment = cls["kind"], cls["demand"], cls["environment"]
        current_dt = _session_clock(session_item)
        next_dt = _session_clock(sessions[idx + 1]) if idx + 1 < len(sessions) else None
        gap_hours = None
        if current_dt and next_dt and next_dt > current_dt:
            gap_hours = round((next_dt - current_dt).total_seconds() / 3600.0, 1)

        if kind == "RACE":
            intra = f'~{ATHLETE_FUELING_PROFILE["race_g_per_hour"]} g CHO/h'
            intra_label = "PRACTISED RACE TARGET"
        elif environment == "OUTDOOR" and kind in ("TEMPO", "THRESHOLD", "VO2"):
            intra = f'~{ATHLETE_FUELING_PROFILE["hard_outdoor_g_per_hour"]} g CHO/h'
            intra_label = "HARD OUTDOOR BASELINE"
        elif environment == "INDOOR":
            intra = "0 g/h usual"
            intra_label = "INDOOR BASELINE"
        else:
            intra = "No fixed target"
            intra_label = "MATCH DURATION / DEMAND"

        post_cho, recovery_need = _post_workout_range(kind, metabolic_context, gap_hours)
        race_state = str((metabolic_context.get("race_strategy") or {}).get("state") or "OFF")
        pressure = str(metabolic_context.get("glycogen_pressure") or "LOW")
        if kind == "RECOVERY" and (race_state == "ACTIVE" or pressure == "HIGH"):
            post_label = "RACE-PREP / GLYCOGEN TOP-UP" if race_state == "ACTIVE" else "GLYCOGEN TOP-UP"
            guidance = "The ride itself is low demand. The higher recovery target, if shown, comes from recent carbohydrate pressure and/or race preparation — not because this recovery ride is being classified as hard."
        elif kind == "RECOVERY":
            post_label = "LIGHT RECOVERY"
            guidance = "Low-demand ride: a normal carbohydrate-containing meal is usually enough unless recent training or the next session raises replenishment priority."
        elif kind == "HEAT":
            post_label = "HEAT RECOVERY"
            guidance = "Moderate carbohydrate replacement plus fluid/electrolyte replacement; heat stress raises recovery priority without automatically making the workout a hard glycogen session."
        elif kind in ("TEMPO", "THRESHOLD", "VO2"):
            post_label = "GLYCOGEN REPLENISHMENT"
            guidance = "Quality work has meaningful carbohydrate demand. Recovery is scaled further by recent workload, time to the next session and race proximity."
        elif kind == "RACE":
            post_label = "POST-RACE REPLENISHMENT"
            guidance = "Race-day recovery is high priority, but immediate intake should still fit the athlete's overall post-race meal and gastrointestinal tolerance."
        else:
            post_label = "LIGHT–MODERATE REPLENISHMENT"
            guidance = "Aerobic work is lower demand than quality training; recovery carbohydrate is adjusted upward only when recent load, short turnaround or race preparation justifies it."

        if gap_hours is not None and gap_hours <= 10:
            timing = f"High urgency · next session ~{gap_hours:g} h later · start within ~30–60 min"
        elif gap_hours is not None and gap_hours <= 20:
            timing = f"Moderate urgency · next session ~{gap_hours:g} h later · within ~60 min is practical"
        else:
            timing = "Normal urgency · integrate with the next normal meal within ~60–90 min"

        plans.append({
            "slot": session_item.get("slot", "Upcoming session"), "title": session_item.get("title") or "Upcoming session",
            "kind": kind, "session_demand": demand, "environment": environment,
            "intra_cho": intra, "intra_label": intra_label,
            "post_cho": post_cho, "post_label": post_label, "recovery_need": recovery_need,
            "guidance": guidance, "timing": timing, "next_gap_hours": gap_hours,
        })
    return plans


# Backward-compatible name retained for any old preview/session object paths.
def build_post_workout_nutrition(next_sessions, metabolic_context=None):
    return build_nutrition_plan(next_sessions, metabolic_context or {
        "glycogen_pressure": "LOW", "race_strategy": {"state": "OFF"}
    })


def personal_baseline_text(metrics):
    pb = metrics.get("personal_baselines") or {}
    def line(label, key):
        item = pb.get(key) or {}
        return f"- {label}: Garmin {item.get('garmin', 'n/a')} | recent {RECENT_BASELINE_DAYS}d {item.get('recent', 'n/a')} | status {item.get('status', 'n/a')}"
    return "\n".join([
        f"PERSONAL BASELINES ({BASELINE_SOURCE}; recent calculations are separate trend context):",
        line("HRV", "hrv"),
        line("Resting HR", "rhr"),
        line("Sleep duration", "sleep"),
        line("Sleep Score", "sleep_score"),
        line("SpO2", "spo2"),
        line("Sleeping HR", "sleeping_hr"),
        f"- Sleeping respiration: Garmin {pb.get('sleeping_respiration', {}).get('garmin', '11 brpm')} | live value not currently imported",
        f"- Awake respiration: Garmin {pb.get('awake_respiration', {}).get('garmin', '13–14 brpm')} | live value not currently imported",
    ])


def ask_claude(data_text, metrics, coach_clock, week_memory, planning_context=None, feeling_trend=None, metabolic_context=None):
    planning_context = planning_context or build_planning_context()
    feeling_trend = feeling_trend or compute_feeling_trend()
    metabolic_context = metabolic_context or {}
    slot_lines = "\n".join(
        f'{i+1}. {slot["label"]} | date {slot["date"]} | restriction {slot.get("restriction", "NONE")}'
        for i, slot in enumerate(coach_clock.get("next_slots") or [])
    )
    prompt = (
        "You are an expert cycling coach inside THE LAB. The athlete may train twice per day, but V12 structured health, availability, restriction and event data outranks the theoretical schedule. "
        "The COACH CLOCK and HEALTH / AVAILABILITY / EVENT CONTEXT below are authoritative. Activities already logged are completed. Slots removed by Python do not exist for you. "
        "A NO_INTENSITY slot permits only easy aerobic/recovery work. A RACE slot is the event itself and must not receive an extra workout.\n\n"
        "{planning_context}\n\n"
        "{clock_context}\n\n"
        "{week_context}\n\n"
        "{subjective_context}\n\n"
        "{baseline_context}\n\n"
        "{metabolic_context}\n\n"
        "ATHLETE CONTEXT:\n{athlete_context}\n\n"
        "Current metrics: Fitness (CTL) {ctl} [{fitness_zone}], Fatigue (ATL) {atl} [{fatigue_zone}], Form (TSB) {tsb} [{form_zone}]. "
        "Health/restriction state is more important than those training-load metrics. If illness or injury explains reduced training, NEVER call the resulting freshness tapering, peaking, race readiness, or improved form. "
        "Instead prioritize health metrics, athlete-reported status and the active restriction. For HRV, resting HR, sleep, Sleep Score and SpO2 use personal Garmin baselines plus recent trend, not population thresholds. "
        "Q1/Q2 sleep quality is a high-priority recovery signal and can partially offset a modest weekday sleep-duration deficit; severe or accumulating short sleep still matters.\n\n"
        "EVENT RULE: an upcoming registered race changes the purpose and spacing of sessions as race day approaches. Respect days-to-race and do not schedule gratuitous fatigue close to the event. "
        "RESTRICTION RULE: temporary restrictions have exact dates. A 12-day no-intensity block means no intentional intensity on any one of those dates, even when CTL/ATL/TSB would otherwise encourage it.\n\n"
        "WEEK-MEMORY RULE: avoid automatically repeating Threshold/TTE, VO2max, Over-Under or sprint/neuromuscular work within about 72h unless there is a clear coaching reason. "
        "Do not repeat dashboard numbers or baseline ranges unnecessarily; interpret what matters.\n\n"
        "Writing style: concise, visual and decisive. training_load, season_distribution and fatigue_signals normally 1-2 useful sentences; season_outlook 2-3; recommendation 3-5 when needed. "
        "For each session give a specific prescription and short rationale.\n\n"
        "Return ONLY valid JSON with exactly these keys:\n"
        '- "training_load": string\n'
        '- "season_distribution": string\n'
        '- "season_outlook": string\n'
        '- "fatigue_signals": string\n'
        '- "recommendation": string\n'
        '- "next_sessions": array of exactly 3 objects, SAME ORDER as valid slots. Each object contains "title", "duration", "intensity", "main_set", "why". Python owns the slot/date and will enforce restrictions after your response. Each ordinary workout must fit within 60 minutes.\n\n'
        "VALID NEXT SLOTS:\n{slot_lines}\n\n"
        "DATA:\n{data_text}"
    ).format(
        planning_context=planning_context_text(planning_context),
        clock_context=coach_clock_text(coach_clock), week_context=week_memory_text(week_memory),
        subjective_context=subjective_context_text(feeling_trend), baseline_context=personal_baseline_text(metrics),
        metabolic_context=metabolic_context_text(metabolic_context), athlete_context=ATHLETE_CONTEXT,
        ctl=metrics["ctl"], fitness_zone=metrics["fitness_zone"],
        atl=metrics["atl"], fatigue_zone=metrics["fatigue_zone"], tsb=metrics["tsb"], form_zone=metrics["form_zone"],
        slot_lines=slot_lines, data_text=data_text,
    )
    resp = requests.post(
        "https://api.anthropic.com/v1/messages",
        headers={"x-api-key": ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01", "content-type": "application/json"},
        json={"model": "claude-sonnet-4-6", "max_tokens": 2600, "messages": [{"role": "user", "content": prompt}]}, timeout=60,
    )
    resp.raise_for_status()
    resp_data = resp.json()
    raw_text = "".join(block.get("text", "") for block in resp_data.get("content", [])).strip()
    if raw_text.startswith("```"):
        raw_text = raw_text.strip("`")
        if raw_text.startswith("json"):
            raw_text = raw_text[4:]
    try:
        parsed = json.loads(raw_text)
    except json.JSONDecodeError as exc:
        preview = raw_text[:300].replace("\n", " ")
        raise json.JSONDecodeError(f"{exc.msg} | raw response preview: {preview}", exc.doc, exc.pos)
    parsed["next_sessions"] = normalize_next_sessions(parsed.get("next_sessions"), coach_clock)
    return parsed



def ask_claude_chat(question, notes, current_data):
    now = get_rome_now()
    today = now.date()
    notes_text = "\n".join(
        "- {}: {}".format(n.get("date", ""), n.get("text", "")) for n in notes
    ) or "(none yet)"

    snapshot_text = "(no snapshot generated yet this session)"
    if current_data:
        snapshot_text = (
            "Fitness (CTL) = {ctl} [{fz}], Fatigue (ATL) = {atl} [{gz}], "
            "Form (TSB) = {tsb} [{fmz}], Energy Bank = {es}/100 ({el})."
        ).format(
            ctl=current_data.get("ctl"), fz=current_data.get("fitness_zone"),
            atl=current_data.get("atl"), gz=current_data.get("fatigue_zone"),
            tsb=current_data.get("tsb"), fmz=current_data.get("form_zone"),
            es=current_data.get("energy_score"), el=current_data.get("energy_label"),
        )

    prompt = (
        "You are the athlete's cycling coach, embedded as a chat box in their personal "
        "dashboard. The current local time is {today_time} Europe/Rome on {today_date} ({today_weekday}). {athlete_context} "
        "Notes the athlete has shared with you before:\n{notes_text}\n\n"
        "Their most recent snapshot: {snapshot_text}\n\n"
        "The athlete just wrote: \"{question}\"\n\n"
        "Respond ONLY with valid JSON (no markdown fences, no extra text) with exactly these "
        "keys:\n"
        '- "answer": a helpful, conversational reply (2-4 sentences, plain prose, no markdown)\n'
        '- "remember": if the athlete\'s message contains a specific, durable fact worth '
        "remembering for future sessions (an injury, an upcoming race, a life event affecting "
        "training, a stated preference or goal), a short factual sentence capturing it in the "
        "third person (e.g. \"Reported mild left knee pain starting July 30\"). If there is "
        "nothing durable worth remembering, use exactly null."
    ).format(
        today_date=today.isoformat(), today_weekday=today.strftime("%A"), today_time=now.strftime("%I:%M %p"),
        athlete_context=ATHLETE_CONTEXT, notes_text=notes_text,
        snapshot_text=snapshot_text, question=question,
    )

    resp = requests.post(
        "https://api.anthropic.com/v1/messages",
        headers={
            "x-api-key": ANTHROPIC_API_KEY,
            "anthropic-version": "2023-06-01",
            "content-type": "application/json",
        },
        json={
            "model": "claude-sonnet-4-6",
            "max_tokens": 400,
            "messages": [{"role": "user", "content": prompt}],
        },
        timeout=60,
    )
    resp.raise_for_status()
    resp_data = resp.json()
    text = "".join(block.get("text", "") for block in resp_data.get("content", []))
    text = text.strip()
    if text.startswith("```"):
        text = text.strip("`")
        if text.startswith("json"):
            text = text[4:]
    parsed = json.loads(text)
    return parsed.get("answer", ""), parsed.get("remember")



def build_vo2max_trend_preview(today=None):
    today = today or date.today()
    wearable = [
        {"date": (today - timedelta(days=49)).isoformat(), "value": 68.0},
        {"date": (today - timedelta(days=35)).isoformat(), "value": 68.4},
        {"date": (today - timedelta(days=21)).isoformat(), "value": 68.7},
        {"date": (today - timedelta(days=7)).isoformat(), "value": 69.0},
        {"date": today.isoformat(), "value": 69.2},
    ]
    performance = [
        {"date": (today - timedelta(days=49)).isoformat(), "value": 70.7},
        {"date": (today - timedelta(days=42)).isoformat(), "value": 70.8},
        {"date": (today - timedelta(days=35)).isoformat(), "value": 71.0},
        {"date": (today - timedelta(days=28)).isoformat(), "value": 71.0},
        {"date": (today - timedelta(days=21)).isoformat(), "value": 71.4},
        {"date": (today - timedelta(days=14)).isoformat(), "value": 71.4},
        {"date": (today - timedelta(days=7)).isoformat(), "value": 71.8},
        {"date": today.isoformat(), "value": 71.8},
    ]
    # Reuse the chart geometry without making API calls.
    original_w = build_wearable_vo2_series
    original_p = build_performance_vo2_series
    try:
        globals()["build_wearable_vo2_series"] = lambda *_args, **_kwargs: wearable
        globals()["build_performance_vo2_series"] = lambda *_args, **_kwargs: performance
        return build_vo2max_trend([])
    finally:
        globals()["build_wearable_vo2_series"] = original_w
        globals()["build_performance_vo2_series"] = original_p


