@app.route("/daily-log", methods=["POST"])
def daily_log():
    if not require_login():
        return redirect(url_for("login"))
    try:
        feeling = int(request.form.get("feeling", ""))
        log_date = request.form.get("log_date") or get_rome_now().date().isoformat()
        activity_context = fetch_activity_context_for_date(log_date)
        note = (request.form.get("note", "") or "").strip()
        save_daily_log(
            feeling=feeling, note=note, status="NORMAL", restriction_type="NONE",
            activity_context=activity_context, log_date=log_date,
        )
        return redirect(url_for("home", notice="NOTED", detail="Daily Log saved · no AI call"))
    except (ValueError, TypeError) as exc:
        return redirect(url_for("home", notice="CHECK INPUT", detail=str(exc) or "Daily Log was not saved"))


@app.route("/daily-log/promote/<log_id>", methods=["POST"])
def daily_log_promote(log_id):
    if not require_login():
        return redirect(url_for("login"))
    row = get_daily_log(log_id)
    note = (row.get("note") if row else "") or ""
    note = note.strip()
    if not note:
        return redirect(url_for("home", notice="NOTHING TO MOVE", detail="That Daily Log has no note"))
    if not memory_text_exists(note):
        add_memory_item(note, "DAILY")
        detail = "Daily note promoted to durable Memory · no AI call"
    else:
        detail = "That note is already in durable Memory"
    return redirect(url_for("home", notice="NOTED", detail=detail))


